async function telegramAnalyseCooldownV276(
  env,
  consume = false
) {
  const binding =
    env.MEME_HUNTER_STATE;

  if (
    !binding ||
    typeof binding.get !==
      "function" ||
    typeof binding.put !==
      "function"
  ) {
    return {
      allowed: true,
      remainingMs: 0,
      persisted: false
    };
  }

  let lastAt = 0;

  try {
    const raw =
      await binding.get(
        TELEGRAM_ANALYSE_STATE_KEY_V276
      );

    if (raw) {
      const parsed =
        JSON.parse(raw);

      lastAt =
        safeNumber(
          parsed?.lastAnalyseAt
        );
    }
  } catch (_) {
    lastAt = 0;
  }

  const elapsed =
    Date.now() -
    lastAt;

  if (
    lastAt > 0 &&
    elapsed <
      TELEGRAM_ANALYSE_COOLDOWN_MS_V276
  ) {
    return {
      allowed: false,
      remainingMs:
        TELEGRAM_ANALYSE_COOLDOWN_MS_V276 -
        elapsed,
      persisted: true
    };
  }

  if (consume) {
    try {
      await binding.put(
        TELEGRAM_ANALYSE_STATE_KEY_V276,
        JSON.stringify({
          lastAnalyseAt:
            Date.now()
        })
      );
    } catch (_) {}
  }

  return {
    allowed: true,
    remainingMs: 0,
    persisted: true
  };
}

function exactKnownSymbolMatchesV276(
  state,
  symbol
) {
  const q =
    String(symbol || "")
      .trim()
      .toLowerCase();

  if (!q) {
    return [];
  }

  const matches =
    [];

  for (
    const watched
    of (
      state?.watchedTokens ||
      []
    )
  ) {
    const watchedSymbol =
      String(
        watched?.metadata?.symbol ||
        watched?.symbol ||
        ""
      )
        .trim()
        .toLowerCase();

    const address =
      normalize(
        watched?.address
      );

    if (
      watchedSymbol === q &&
      isAddress(address) &&
      !knownQuote(address)
    ) {
      matches.push({
        address,
        symbol:
          watched?.metadata?.symbol ||
          watched?.symbol ||
          null,
        name:
          watched?.metadata?.name ||
          watched?.name ||
          null,
        source:
          "PERSISTED_WATCHLIST_V276"
      });
    }
  }

  const unique =
    new Map();

  for (const row of matches) {
    unique.set(
      row.address,
      row
    );
  }

  return [
    ...unique.values()
  ];
}

async function dexResolveSymbolV276(
  symbol,
  budget
) {
  const q =
    String(symbol || "")
      .trim();

  if (!q) {
    return {
      status:
        "MISSING_SYMBOL",
      matches:
        []
    };
  }

  if (
    !consumeBudget(
      budget,
      "analysis",
      "DEXSCREENER_SYMBOL_RESOLUTION_V276"
    )
  ) {
    return {
      status:
        "COMMAND_BUDGET_EXHAUSTED",
      matches:
        []
    };
  }

  try {
    const controller =
      new AbortController();

    const timer =
      setTimeout(
        () =>
          controller.abort(),
        4500
      );

    let response;

    try {
      response =
        await fetch(
          `${DEXSCREENER_BASE}/latest/dex/search?q=${encodeURIComponent(q)}`,
          {
            signal:
              controller.signal
          }
        );
    } finally {
      clearTimeout(timer);
    }

    if (!response.ok) {
      return {
        status:
          `DEXSCREENER_HTTP_${response.status}`,
        matches:
          []
      };
    }

    const data =
      await response.json();

    const pairs =
      Array.isArray(
        data?.pairs
      )
        ? data.pairs
        : [];

    const target =
      q.toLowerCase();

    const candidateRows =
      [];

    for (const pair of pairs) {
      if (
        String(
          pair?.chainId ||
          ""
        ).toLowerCase() !==
        "robinhood"
      ) {
        continue;
      }

      const sides = [
        pair?.baseToken,
        pair?.quoteToken
      ];

      for (const token of sides) {
        const tokenSymbol =
          String(
            token?.symbol ||
            ""
          )
            .trim()
            .toLowerCase();

        const address =
          normalize(
            token?.address
          );

        if (
          tokenSymbol !== target ||
          !isAddress(address) ||
          address === ZERO ||
          knownQuote(address)
        ) {
          continue;
        }

        candidateRows.push({
          address,
          symbol:
            token?.symbol ||
            q,
          name:
            token?.name ||
            null,
          liquidityUsd:
            safeNumber(
              pair?.liquidity?.usd
            ),
          source:
            "DEXSCREENER_EXACT_SYMBOL_ROBINHOOD_V276"
        });
      }
    }

    const byAddress =
      new Map();

    for (const row of candidateRows) {
      const prior =
        byAddress.get(
          row.address
        );

      if (
        !prior ||
        safeNumber(
          row?.liquidityUsd
        ) >
        safeNumber(
          prior?.liquidityUsd
        )
      ) {
        byAddress.set(
          row.address,
          row
        );
      }
    }

    return {
      status:
        byAddress.size
          ? "EXACT_SYMBOL_MATCHES_FOUND"
          : "NO_EXACT_ROBINHOOD_SYMBOL_MATCH",
      matches:
        [
          ...byAddress.values()
        ].sort(
          (a, b) =>
            safeNumber(
              b?.liquidityUsd
            ) -
            safeNumber(
              a?.liquidityUsd
            )
        )
    };
  } catch (error) {
    return {
      status:
        "DEXSCREENER_SYMBOL_RESOLUTION_ERROR",
      error:
        errorString(error),
      matches:
        []
    };
  }
}

async function resolveTelegramAnalyseTargetV276(
  query,
  state,
  budget
) {
  const raw =
    String(query || "")
      .trim();

  if (!raw) {
    return {
      status:
        "MISSING_QUERY",
      address:
        null,
      matches:
        []
    };
  }

  const normalized =
    normalize(raw);

  if (
    isAddress(normalized)
  ) {
    return {
      status:
        "MATCHED_ADDRESS",
      address:
        normalized,
      matches: [
        {
          address:
            normalized,
          source:
            "DIRECT_ADDRESS_V276"
        }
      ]
    };
  }

  const known =
    exactKnownSymbolMatchesV276(
      state,
      raw
    );

  if (
    known.length ===
    1
  ) {
    return {
      status:
        "MATCHED_KNOWN_SYMBOL",
      address:
        known[0].address,
      matches:
        known
    };
  }

  if (
    known.length >
    1
  ) {
    return {
      status:
        "AMBIGUOUS_SYMBOL",
      address:
        null,
      matches:
        known
    };
  }

  const dex =
    await dexResolveSymbolV276(
      raw,
      budget
    );

  if (
    dex.matches.length ===
    1
  ) {
    return {
      status:
        "MATCHED_DEXSCREENER_SYMBOL",
      address:
        dex.matches[0].address,
      matches:
        dex.matches,
      resolverStatus:
        dex.status
    };
  }

  if (
    dex.matches.length >
    1
  ) {
    return {
      status:
        "AMBIGUOUS_SYMBOL",
      address:
        null,
      matches:
        dex.matches,
      resolverStatus:
        dex.status
    };
  }

  return {
    status:
      dex.status ||
      "NOT_FOUND",
    address:
      null,
    matches:
      []
  };
}

function telegramAnalyseAmbiguousMessageV276(
  query,
  matches
) {
  const lines = [
    `⚠️ <b>More than one Robinhood token uses ${escapeHtml(String(query || ""))}.</b>`,
    "",
    "I won't guess. Use the contract address:",
    ""
  ];

  for (
    const row
    of (
      matches ||
      []
    ).slice(0, 8)
  ) {
    lines.push(
      `✅ ${escapeHtml(
        row?.symbol ||
        "TOKEN"
      )} — <code>${escapeHtml(
        row?.address ||
        ""
      )}</code>`
    );
  }

  return lines.join("\n");
}


function telegramAnalyseDirectionalV276(
  candidate
) {
  const exact =
    candidate
      ?.onChainVerifiedFlowV212
      ?.windows ||
    {};

  const market =
    candidate
      ?.market
      ?.directionalFlow ||
    {};

  for (
    const key
    of [
      "h1",
      "m15",
      "m5",
      "h24"
    ]
  ) {
    const row =
      exact?.[key]?.verified ===
        true
        ? exact[key]
        : market?.[key]?.verified ===
            true
          ? market[key]
          : null;

    if (!row) {
      continue;
    }

    const buy =
      Number(
        row?.buyVolumeUsd
      );

    const sell =
      Number(
        row?.sellVolumeUsd
      );

    const net =
      Number(
        row?.netFlowUsd
      );

    const pressure =
      Number(
        row?.buyPressureUsd
      );

    if (
      Number.isFinite(buy) &&
      Number.isFinite(sell) &&
      Number.isFinite(net) &&
      Number.isFinite(pressure)
    ) {
      return {
        verified: true,
        window: key,
        buyVolumeUsd: buy,
        sellVolumeUsd: sell,
        netFlowUsd: net,
        buyPressureUsd: pressure,
        source:
          exact?.[key]?.verified ===
            true
            ? "ONCHAIN_VERIFIED_FLOW"
            : "MARKET_DIRECTIONAL_FLOW"
      };
    }
  }

  return {
    verified: false,
    window: null,
    buyVolumeUsd: null,
    sellVolumeUsd: null,
    netFlowUsd: null,
    buyPressureUsd: null,
    source: null
  };
}


/* =========================================================
   V284 MANUAL VERIFIED-USD TELEGRAM PARITY
   ========================================================= */

function telegramAnalyseVerifiedUsdLinesV284(
  candidate
) {
  const observed =
    candidate?.onChainVerifiedFlowV212;

  const diagnostic =
    candidate?.telegramVerifiedUsdDiagnosticV213 ||
    telegramVerifiedUsdDiagnosticV213(
      candidate
    );

  const eligible =
    observed?.verified === true &&
    diagnostic
      ?.telegramVerifiedUsdSectionEligible === true;

  const money = value =>
    value !== null &&
    value !== undefined
      ? telegramMoneyV271(value)
      : "UNVERIFIED";

  const percent = value =>
    value !== null &&
    value !== undefined
      ? percentDisplay(value)
      : "UNVERIFIED";

  const lines = [
    "✅ <b>Verified On-chain USD (observed by bot)</b>"
  ];

  const pushWindow = (
    label,
    key
  ) => {
    const row =
      observed?.windows?.[key];

    if (
      eligible &&
      row?.verified === true
    ) {
      lines.push(
        `🟢 ${label} Verified Buys: <b>${safeNumber(row.buys)}</b> — <b>${money(row.buyVolumeUsd)}</b>`,
        `🔴 ${label} Verified Sells: <b>${safeNumber(row.sells)}</b> — <b>${money(row.sellVolumeUsd)}</b>`,
        `📈 ${label} Verified Net: <b>${money(row.netFlowUsd)}</b>`,
        `💵 ${label} Verified USD Buy Pressure: <b>${percent(row.buyPressureUsd)}</b>`
      );
      return;
    }

    lines.push(
      `🟢 ${label} Verified Buys: <b>UNVERIFIED</b>`,
      `🔴 ${label} Verified Sells: <b>UNVERIFIED</b>`,
      `📈 ${label} Verified Net: <b>UNVERIFIED</b>`,
      `💵 ${label} Verified USD Buy Pressure: <b>UNVERIFIED</b>`
    );
  };

  pushWindow("5m", "m5");
  pushWindow("15m", "m15");
  pushWindow("1h", "h1");
  pushWindow("6h", "h6");
  pushWindow("12h", "h12");
  pushWindow("24h", "h24");

  const source = String(observed?.source || "");

  lines.push(
    eligible && source === "BITQUERY_TRADING_TRADES_MANUAL_V285"
      ? "ℹ️ <i>Verified candidate-matched Bitquery Robinhood trades. Documented duplicate legs are removed; incomplete or routed-ambiguous windows remain UNVERIFIED.</i>"
      : eligible
        ? "ℹ️ <i>Verified exact V4 swaps observed by this bot; not claimed as complete market-window totals.</i>"
        : "ℹ️ <i>No candidate-matched exact-USD evidence was verified for this analysis; dollar amounts are not inferred from unverified market activity counts.</i>"
  );

  return lines;
}




/* =========================================================
   V285 MANUAL BITQUERY DIRECTIONAL USD
   ========================================================= */

const TELEGRAM_ANALYSE_BITQUERY_TRADE_LIMIT_V285 = 300;

function manualBitqueryWindowV285(rows, windowMs, nowMs, coverageComplete) {
  const selected = rows.filter(
    row => row.observedAt >= nowMs - windowMs && row.observedAt <= nowMs
  );

  const unverified = (status, observedTrades = 0) => ({
    verified: false,
    status,
    observedTrades,
    buys: 0,
    sells: 0,
    buyVolumeUsd: null,
    sellVolumeUsd: null,
    netFlowUsd: null,
    buyPressureUsd: null,
    fullMarketCoverageVerified: false
  });

  if (!coverageComplete) return unverified("WINDOW_COVERAGE_INCOMPLETE_V285");
  if (!selected.length) return unverified("NO_INDEXED_TRADES_IN_WINDOW_V285");

  /*
   * After Bitquery's documented duplicate-leg key is applied, more than one
   * candidate leg with the same tx+side can still be routed activity. Do not
   * sum it: routed-leg inflation is explicitly documented on Robinhood.
   */
  const txSides = new Map();
  for (const row of selected) {
    const key = `${row.txHash}|${row.side}`;
    txSides.set(key, (txSides.get(key) || 0) + 1);
  }
  if ([...txSides.values()].some(count => count > 1)) {
    return unverified("ROUTED_MULTI_LEG_AMBIGUITY_V285", selected.length);
  }

  let buys = 0, sells = 0, buyVolumeUsd = 0, sellVolumeUsd = 0;
  for (const row of selected) {
    if (row.side === "buy") {
      buys++;
      buyVolumeUsd += row.usd;
    } else {
      sells++;
      sellVolumeUsd += row.usd;
    }
  }

  const total = buyVolumeUsd + sellVolumeUsd;
  if (!(buys + sells) || !(total > 0)) {
    return unverified("NO_POSITIVE_EXACT_USD_ROWS_V285");
  }

  return {
    verified: true,
    status: "VERIFIED_BITQUERY_INDEXED_WINDOW_V285",
    observedTrades: buys + sells,
    buys,
    sells,
    buyVolumeUsd,
    sellVolumeUsd,
    netFlowUsd: buyVolumeUsd - sellVolumeUsd,
    buyPressureUsd: (buyVolumeUsd / total) * 100,
    fullMarketCoverageVerified: false
  };
}

async function manualBitqueryDirectionalUsdV285(env, budget, state, candidate) {
  const base = {
    attempted: false,
    verified: false,
    status: "NOT_ATTEMPTED",
    requestsUsed: 0,
    httpStatus: null,
    rawRows: 0,
    rows: 0,
    duplicatesRemoved: 0,
    error: null,
    flow: null
  };

  const currentDiagnostic =
    candidate?.telegramVerifiedUsdDiagnosticV213 ||
    telegramVerifiedUsdDiagnosticV213(candidate);

  if (
    candidate?.onChainVerifiedFlowV212?.verified === true &&
    currentDiagnostic?.telegramVerifiedUsdSectionEligible === true
  ) {
    return {...base, status: "ALREADY_HAS_VERIFIED_DIRECTIONAL_USD"};
  }

  const address = normalize(candidate?.address);
  const token = String(env.BITQUERY_ACCESS_TOKEN || "").trim();

  if (candidate?.validERC20 !== true || !isAddress(address) || knownQuote(address)) {
    return {...base, status: "CANDIDATE_NOT_ELIGIBLE"};
  }
  if (!token) return {...base, status: "BITQUERY_NOT_CONFIGURED"};
  if (bitquery402CoolingV251(state)) {
    return {...base, status: "BITQUERY_402_COOLDOWN_ACTIVE"};
  }
  if (!budgetAvailable(budget, "analysis")) {
    return {...base, status: "NO_SPARE_MANUAL_BUDGET"};
  }

  const before = safeNumber(budget.totalUsed);
  if (!consumeBudget(budget, "analysis", "BITQUERY_MANUAL_DIRECTIONAL_USD_V285")) {
    return {...base, status: "MANUAL_BUDGET_PROTECTED"};
  }

  const query = `{
    Trading {
      ManualDirectionalV285: Trades(
        limit: {count: ${TELEGRAM_ANALYSE_BITQUERY_TRADE_LIMIT_V285}}
        orderBy: {descending: Block_Time}
        where: {
          Block: {Time: {since_relative: {hours_ago: 24}}}
          Pair: {
            Token: {Address: {is: "${address}"}}
            Market: {NetworkBid: {is: "bid:robinhood"}}
          }
        }
      ) {
        Block {Time}
        Side
        Amounts {Base}
        AmountsInUsd {Base}
        Trader {Address}
        TransactionHeader {Hash}
        Pair {
          Token {Address}
          QuoteToken {Address Symbol}
          Market {Protocol ProtocolFamily Network}
        }
      }
    }
  }`;

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 4500);
  let response, payload;

  try {
    response = await fetch(BITQUERY_GRAPHQL_V2, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        accept: "application/json",
        authorization: `Bearer ${token}`
      },
      body: JSON.stringify({query}),
      signal: controller.signal
    });
    try { payload = await response.json(); } catch (_) { payload = null; }
  } catch (error) {
    return {
      ...base,
      attempted: true,
      requestsUsed: safeNumber(budget.totalUsed) - before,
      status: "BITQUERY_REQUEST_FAILED_V285",
      error: errorString(error)
    };
  } finally {
    clearTimeout(timer);
  }

  if (!response.ok) {
    if (response.status === 402) registerBitquery402V251(state);
    return {
      ...base,
      attempted: true,
      requestsUsed: safeNumber(budget.totalUsed) - before,
      httpStatus: response.status,
      status: `BITQUERY_HTTP_${response.status}_V285`,
      error: payload?.errors?.[0]?.message || "BITQUERY_HTTP_ERROR_V285"
    };
  }

  registerBitqueryHttpSuccessV251(state);

  if (Array.isArray(payload?.errors) && payload.errors.length) {
    return {
      ...base,
      attempted: true,
      requestsUsed: safeNumber(budget.totalUsed) - before,
      httpStatus: response.status,
      status: "BITQUERY_GRAPHQL_ERROR_V285",
      error: payload.errors.map(row => row?.message).filter(Boolean).join(" | ").slice(0, 320)
    };
  }

  const raw = Array.isArray(payload?.data?.Trading?.ManualDirectionalV285)
    ? payload.data.Trading.ManualDirectionalV285
    : [];

  const accepted = [];
  for (const row of raw) {
    const returned = normalize(row?.Pair?.Token?.Address);
    const quoteAddress = normalize(row?.Pair?.QuoteToken?.Address);
    const quoteSymbol = row?.Pair?.QuoteToken?.Symbol || null;
    const side = String(row?.Side || "").toLowerCase();
    const usd = Number(row?.AmountsInUsd?.Base);
    const timeText = String(row?.Block?.Time || "");
    const observedAt = Date.parse(timeText);
    const txHash = String(row?.TransactionHeader?.Hash || "").toLowerCase();
    const trader = String(row?.Trader?.Address || "").toLowerCase();
    const baseAmount = String(row?.Amounts?.Base ?? "");

    if (
      returned !== address ||
      !knownQuoteMetadata(quoteAddress, quoteSymbol) ||
      !["buy", "sell"].includes(side) ||
      !/^0x[a-f0-9]{64}$/.test(txHash) ||
      !Number.isFinite(usd) || usd <= 0 ||
      !Number.isFinite(observedAt)
    ) continue;

    accepted.push({
      side, usd, observedAt, txHash, trader, baseAmount,
      timeText, quoteSymbol: String(quoteSymbol || "").toUpperCase()
    });
  }

  /*
   * Bitquery documents this exact Robinhood Trading.Trades dedup tuple:
   * hash + block time + side + base amount + quote symbol + trader.
   */
  const unique = new Map();
  for (const row of accepted) {
    const key = [
      row.txHash, row.timeText, row.side, row.baseAmount, row.quoteSymbol, row.trader
    ].join("|");
    if (!unique.has(key)) unique.set(key, row);
  }
  const rows = [...unique.values()].sort((a, b) => b.observedAt - a.observedAt);

  const times = raw
    .map(row => Date.parse(String(row?.Block?.Time || "")))
    .filter(Number.isFinite)
    .sort((a, b) => a - b);

  const oldest = times.length ? times[0] : null;
  const hitCap = raw.length >= TELEGRAM_ANALYSE_BITQUERY_TRADE_LIMIT_V285;
  const nowMs = Date.now();
  const covered = ms => !hitCap || (Number.isFinite(oldest) && oldest <= nowMs - ms);

  const windows = {
    m5: manualBitqueryWindowV285(rows, V180_WINDOW_MS.m5, nowMs, covered(V180_WINDOW_MS.m5)),
    m15: manualBitqueryWindowV285(rows, V180_WINDOW_MS.m15, nowMs, covered(V180_WINDOW_MS.m15)),
    h1: manualBitqueryWindowV285(rows, V180_WINDOW_MS.h1, nowMs, covered(V180_WINDOW_MS.h1)),
    h6: manualBitqueryWindowV285(rows, V180_WINDOW_MS.h6, nowMs, covered(V180_WINDOW_MS.h6)),
    h12: manualBitqueryWindowV285(rows, V180_WINDOW_MS.h12, nowMs, covered(V180_WINDOW_MS.h12)),
    h24: manualBitqueryWindowV285(rows, V180_WINDOW_MS.h24, nowMs, covered(V180_WINDOW_MS.h24))
  };

  const verifiedWindows = Object.entries(windows)
    .filter(([, row]) => row?.verified === true)
    .map(([key]) => key);

  const flow = {
    verified: verifiedWindows.length > 0,
    source: "BITQUERY_TRADING_TRADES_MANUAL_V285",
    interpretation: "VERIFIED_INDEXED_OBSERVED_NOT_FULL_MARKET_WINDOW",
    tokenAddress: address,
    poolIds: [],
    recordCount: rows.length,
    windows,
    verifiedWindows,
    status: verifiedWindows.length
      ? "CANDIDATE_MATCHED_VERIFIED_BITQUERY_USD_AVAILABLE_V285"
      : raw.length
        ? "NO_SAFE_VERIFIED_BITQUERY_WINDOWS_V285"
        : "NO_BITQUERY_TRADES_RETURNED_V285"
  };

  return {
    ...base,
    attempted: true,
    verified: flow.verified,
    status: flow.status,
    requestsUsed: safeNumber(budget.totalUsed) - before,
    httpStatus: response.status,
    rawRows: raw.length,
    rows: rows.length,
    duplicatesRemoved: Math.max(0, accepted.length - rows.length),
    flow
  };
}

function applyManualBitqueryDirectionalUsdV285(candidate, result) {
  if (!candidate || result?.verified !== true || result?.flow?.verified !== true) {
    return candidate;
  }
  const updated = {
    ...candidate,
    onChainVerifiedFlowV212: result.flow,
    manualBitqueryDirectionalUsdV285: true
  };
  updated.telegramVerifiedUsdDiagnosticV213 =
    telegramVerifiedUsdDiagnosticV213(updated);
  return updated;
}


async function historicalAlertEvidenceV277(
  env,
  address
) {
  const target =
    normalize(address);

  if (!target) {
    return {
      found: false,
      entry: null,
      status:
        "INVALID_ADDRESS",
      historyStatus: null,
      retainedCount: 0,
      maximumEntries:
        ALERT_HISTORY_MAX_ENTRIES_V268,
      key:
        ALERT_HISTORY_KEY_V268
    };
  }

  const report =
    await alertHistoryV268(
      env
    );

  const entries =
    Array.isArray(
      report?.entries
    )
      ? report.entries
      : [];

  const entry =
    entries.find(
      item =>
        normalize(
          item?.address ||
          item?.snapshot
            ?.alert
            ?.address
        ) ===
        target
    ) ||
    null;

  return {
    found:
      Boolean(entry),
    entry,
    status:
      entry
        ? "HISTORICAL_ALERT_FOUND"
        : (
            report?.status ||
            "NO_HISTORICAL_ALERT"
          ),
    historyStatus:
      report?.status || null,
    retainedCount:
      safeNumber(report?.count),
    maximumEntries:
      safeNumber(
        report?.maximumEntries
      ) ||
      ALERT_HISTORY_MAX_ENTRIES_V268,
    key:
      report?.key ||
      ALERT_HISTORY_KEY_V268,
    binding:
      report?.binding || null,
    targetAddress:
      target,
    targetPresentInRetainedHistory:
      Boolean(entry)
  };
}


function hydrateManualWatchedFromAlertV277(
  watched,
  historical
) {
  const hydrated =
    watched &&
    typeof watched ===
      "object"
      ? watched
      : {};

  const entry =
    historical?.entry ||
    null;

  const snapshot =
    entry?.snapshot ||
    null;

  const candidate =
    snapshot?.candidate ||
    null;

  const identity =
    candidate
      ?.onChainPoolIdentityV153 ||
    null;

  if (
    !hydrated.metadata &&
    (
      entry?.symbol ||
      entry?.name
    )
  ) {
    hydrated.metadata = {
      validERC20: true,
      symbol:
        entry?.symbol ||
        null,
      name:
        entry?.name ||
        null,
      source:
        "V268_VERIFIED_ALERT_HISTORY_V277",
      recoveredAt:
        Date.now()
    };
  }

  const poolId =
    normalize(
      identity?.poolId ||
      identity?.pairAddress
    );

  const quote =
    normalize(
      identity
        ?.quoteTokenAddress
    );

  const token =
    normalize(
      hydrated?.address
    );

  const canRestorePool =
    identity?.verified ===
      true &&
    /^0x[0-9a-f]{64}$/.test(
      String(poolId || "")
    ) &&
    isAddress(token) &&
    isAddress(quote) &&
    (
      quote === ZERO ||
      knownQuote(quote)
    );

  if (canRestorePool) {
    hydrated.pools =
      Array.isArray(
        hydrated.pools
      )
        ? hydrated.pools
        : [];

    const exists =
      hydrated.pools.some(
        pool =>
          normalize(
            pool?.poolId
          ) ===
          poolId
      );

    if (!exists) {
      /*
       * The V268 alert snapshot already verified candidate + known-quote
       * membership for this exact PoolId. Currency order is not used as
       * trade direction here; onChainPoolIdentityV153 only requires the
       * candidate and a verified quote to be members of the PoolId.
       */
      hydrated.pools.push({
        poolId,
        currency0:
          token,
        currency1:
          quote,
        blockNumber:
          identity?.blockNumber ||
          null,
        transactionHash:
          identity
            ?.transactionHash ||
          null,
        source:
          "V268_VERIFIED_ALERT_POOL_RESTORED_V277",
        historicalVerified:
          true
      });
    }
  }

  return {
    watched:
      hydrated,
    historicalAlertFound:
      historical?.found ===
      true,
    restoredPoolIdentity:
      canRestorePool,
    restoredPoolId:
      canRestorePool
        ? poolId
        : null
  };
}


async function manualMarketFreshGateV277(
  env,
  consume = false
) {
  const {
    kv
  } = getKV(
    env
  );

  if (!kv) {
    return {
      allowed: true,
      remainingMs: 0,
      persisted: false
    };
  }

  let lastAt = 0;

  try {
    const raw =
      await kv.get(
        TELEGRAM_ANALYSE_MARKET_STATE_KEY_V277
      );

    if (raw) {
      const parsed =
        JSON.parse(raw);

      lastAt =
        safeNumber(
          parsed
            ?.lastFreshMarketAt
        );
    }
  } catch (_) {
    lastAt = 0;
  }

  const elapsed =
    Date.now() -
    lastAt;

  if (
    lastAt > 0 &&
    elapsed <
      TELEGRAM_ANALYSE_MARKET_SPACING_MS_V277
  ) {
    return {
      allowed: false,
      remainingMs:
        TELEGRAM_ANALYSE_MARKET_SPACING_MS_V277 -
        elapsed,
      persisted: true
    };
  }

  if (consume) {
    try {
      await kv.put(
        TELEGRAM_ANALYSE_MARKET_STATE_KEY_V277,
        JSON.stringify({
          lastFreshMarketAt:
            Date.now()
        })
      );
    } catch (_) {}
  }

  return {
    allowed: true,
    remainingMs: 0,
    persisted: true
  };
}


function prepareManualMarketStateV277(
  isolatedState,
  originalState,
  marketGate
) {
  const originalDex =
    dexService(
      originalState
    );

  const isolatedDex =
    dexService(
      isolatedState
    );

  const actualCooldownUntil =
    safeNumber(
      originalDex
        ?.cooldownUntil
    );

  const actual429Cooldown =
    actualCooldownUntil >
    Date.now();

  if (
    marketGate?.allowed !==
      true ||
    actual429Cooldown
  ) {
    return {
      freshOverrideEnabled:
        false,
      reason:
        actual429Cooldown
          ? "DEXSCREENER_429_COOLDOWN_PRESERVED"
          : "MANUAL_MARKET_SPACING_V277",
      actualDexCooldownUntil:
        actualCooldownUntil ||
        null
    };
  }

  /*
   * The manual command has its own provider spacing and operates on a
   * cloned state. Clear scanner scheduling guards only inside that clone.
   * Real provider 429 cooldown is checked above and never bypassed.
   */
  isolatedDex.lastRequestAt =
    0;

  isolatedDex
    .priorityFreshReservation =
    {
      address: null,
      reservedAt: null,
      eligibleAt: null,
      lastServedAt: null,
      attempts: 0
    };

  const recovery =
    marketProviderRecoveryV157(
      isolatedState
    );

  recovery.blockDexUntil =
    null;

  recovery
    .recoveringProviderUsedThisScan =
    null;

  return {
    freshOverrideEnabled:
      true,
    reason:
      "ISOLATED_MANUAL_FRESH_MARKET_V277",
    actualDexCooldownUntil:
      actualCooldownUntil ||
      null
  };
}


function manualEvidenceCompletenessV277(
  candidate
) {
  const marketVerified =
    candidate
      ?.market
      ?.verified ===
    true;

  const poolVerified =
    candidate
      ?.onChainPoolIdentityV153
      ?.verified ===
    true;

  const erc20Verified =
    candidate
      ?.validERC20 ===
    true;

  const directionalVerified =
    telegramAnalyseDirectionalV276(
      candidate
    )?.verified ===
    true;

  const coreComplete =
    erc20Verified &&
    marketVerified;

  return {
    erc20Verified,
    marketVerified,
    poolVerified,
    directionalVerified,
    coreComplete,
    scoringPresentation:
      coreComplete
        ? "NORMAL"
        : "PROVISIONAL_CORE_MARKET_UNVERIFIED"
  };
}


function telegramRawScoreV277(
  value,
  suffix,
  completeness
) {
  const raw =
    `${safeNumber(value)}/100${suffix ? ` ${escapeHtml(suffix)}` : ""}`;

  return completeness
    ?.coreComplete ===
      true
      ? raw
      : `${raw} — PROVISIONAL`;
}


function telegramAnalyseRequestBreakdownV279(
  telemetry
) {
  const consumed =
    telemetry
      ?.requestBreakdownV279
      ?.consumed;

  if (
    !consumed ||
    typeof consumed !==
      "object"
  ) {
    return "UNAVAILABLE";
  }

  const entries =
    Object.entries(consumed)
      .filter(
        ([, count]) =>
          safeNumber(count) > 0
      )
      .sort(
        (a, b) =>
          safeNumber(b[1]) -
          safeNumber(a[1])
      );

  if (!entries.length) {
    return "NONE";
  }

  return entries
    .map(
      ([type, count]) =>
        `${escapeHtml(type)}×${safeNumber(count)}`
    )
    .join(" | ");
}

function telegramMomentumEvidenceV279(
  candidate
) {
  const momentum =
    candidate?.momentum || {};

  if (momentum?.verified !== true) {
    return "UNVERIFIED";
  }

  const evidence = [];

  if (
    candidate?.market?.verified ===
      true
  ) {
    evidence.push("MARKET/HISTORY");
  }

  if (
    candidate?.holders
      ?.countersVerified === true
  ) {
    evidence.push("HOLDERS");
  }

  if (
    momentum
      ?.directionalUsdPressureV151
      ?.verified === true
  ) {
    evidence.push("VERIFIED USD FLOW");
  }

  if (
    momentum
      ?.ponsCurveMomentumV218
      ?.verified === true
  ) {
    evidence.push("PONS");
  }

  if (
    candidate
      ?.liveMomentumActivityV152
      ?.verified === true
  ) {
    evidence.push("LIVE V4");
  } else {
    evidence.push("LIVE V4 UNVERIFIED");
  }

  return evidence.length
    ? evidence.join(" + ")
    : "VERIFIED SCORE; SOURCE DETAIL UNAVAILABLE";
}

