      toBlock:
        manualLiveV4ResultV283?.toBlock ?? null,
      swaps:
        manualLiveV4ResultV283?.swaps ?? null,
      liquidityEvents:
        manualLiveV4ResultV283?.liquidityEvents ?? null,
      requestsUsed:
        safeNumber(
          manualLiveV4ResultV283?.requestsUsed
        ),
