/* =========================================================
   V313 READ-ONLY FROZEN-SNAPSHOT LEARNING + SAMPLE QUALITY
   ========================================================= */
function medianV312(values) {
  const clean = (Array.isArray(values) ? values : [])
    .map(Number)
    .filter(value => Number.isFinite(value) && value > 0)
    .sort((a, b) => a - b);
  if (!clean.length) return null;
  const mid = Math.floor(clean.length / 2);
  return clean.length % 2 ? clean[mid] : (clean[mid - 1] + clean[mid]) / 2;
}

function learningSampleStrengthV313(n) {
  const count = Number(n) || 0;
  if (count < 3) return 'TOO_SMALL';
  if (count < 10) return 'VERY_SMALL';
  if (count < 30) return 'SMALL';
  if (count < 100) return 'BUILDING';
  return 'STRONGER';
}

function learningGroupStatsV312(records) {
  const multiples = (Array.isArray(records) ? records : [])
    .map(record => Number(record?.athMultipleByMarketCap))
    .filter(value => Number.isFinite(value) && value > 0);
  if (!multiples.length) return null;

  const total = multiples.reduce((sum, value) => sum + value, 0);
  const average = total / multiples.length;
  const median = medianV312(multiples);
  const hit125 = multiples.filter(value => value >= 1.25).length;
  const hit2 = multiples.filter(value => value >= 2).length;
  const below125 = multiples.length - hit125;
  const neverAboveEntryV407 = multiples.filter(value => value <= 1.000001).length;
  const wentAboveEntryV407 = multiples.filter(value => value > 1.000001).length;
  const top = Math.max(...multiples);
  const topSharePct = total > 0 ? (top / total) * 100 : null;
  const averageExTop = multiples.length > 1 ? (total - top) / (multiples.length - 1) : null;

  return {
    n: multiples.length,
    average,
    median,
    hit125,
    hit2,
    below125,
    neverAboveEntryV407,
    wentAboveEntryV407,
    top,
    topSharePct,
    averageExTop,
    sampleStrength: learningSampleStrengthV313(multiples.length)
  };
}

function learningStatsTextV312(stats) {
  if (!stats) return 'n=0';
  return `n=${stats.n} [${stats.sampleStrength}] | med ${telegramMultipleV271(stats.median)} | avg ${telegramMultipleV271(stats.average)} | ≥1.25x ${stats.hit125}/${stats.n} | &lt;1.25x ${stats.below125}/${stats.n} | ≥2x ${stats.hit2}/${stats.n}`;
}

function learningOutlierTextV313(stats) {
  if (!stats) return 'Outlier check: UNVERIFIED';
  const share = Number.isFinite(Number(stats.topSharePct))
    ? `${Number(stats.topSharePct).toFixed(1)}%`
    : 'UNVERIFIED';
  const exTop = Number.isFinite(Number(stats.averageExTop))
    ? telegramMultipleV271(stats.averageExTop)
    : 'N/A';
  return `top ${telegramMultipleV271(stats.top)} = ${share} of summed multiples | avg excl top ${exTop}`;
}

function learningBandV312(value, bands) {
  const n = Number(value);
  if (!Number.isFinite(n)) return null;
  for (const band of bands) {
    if (n >= band.min && n <= band.max) return band.label;
  }
  return null;
}

function learningMaturityCohortV316(records, minAgeMs, nowMs = Date.now()) {
  return (Array.isArray(records) ? records : []).filter(record => {
    const entryAt = Number(record?.entryTimestamp);
    return Number.isFinite(entryAt) && entryAt > 0 && (nowMs - entryAt) >= minAgeMs;
  });
}

function learningMaturityLineV316(label, records) {
  const stats = learningGroupStatsV312(records);
  if (!stats) return `• ${label}: n=0 — no eligible frozen calls yet`;
  return `• ${label}: ${learningStatsTextV312(stats)} | avg excl top ${Number.isFinite(Number(stats.averageExTop)) ? telegramMultipleV271(stats.averageExTop) : 'N/A'}`;
}

function fixedHorizonLearningStatsV317(records, key) {
  const rows = [];
  for (const record of Array.isArray(records) ? records : []) {
    const outcome = record?.fixedHorizonOutcomesV317?.outcomes?.[key];
    const multiple = Number(outcome?.multipleByMarketCap);
    if (outcome?.verified === true && outcome?.frozen === true && Number.isFinite(multiple) && multiple > 0) rows.push({ ...record, athMultipleByMarketCap: multiple });
  }
  return learningGroupStatsV312(rows);
}

function fixedHorizonLearningLineV317(label, records, key) {
  const stats = fixedHorizonLearningStatsV317(records, key);
  if (!stats) return `• ${label}: n=0 — no forward-only verified outcomes captured yet`;
  return `• ${label}: ${learningStatsTextV312(stats)} | avg excl top ${Number.isFinite(Number(stats.averageExTop)) ? telegramMultipleV271(stats.averageExTop) : 'N/A'}`;
}

function frozenLearningMessageV312(state) {
  const all = callPerformanceEntriesV271(state);
  const records = all.filter(record => {
    const snap = record?.entrySignalSnapshotV309;
    const ath = Number(record?.athMultipleByMarketCap);
    return snap?.frozenAtSuccessfulCall === true &&
      snap?.laterEvidenceBackfillAllowed === false &&
      Number.isFinite(ath) && ath > 0;
  });

  if (!records.length) {
    return [
      '🧠 <b>Frozen Entry Learning — V317</b>',
      '',
      'No frozen V309+ entry snapshots with verified ATH outcomes are stored yet.',
      '',
      '<i>Read-only. No scoring changes and zero provider requests.</i>'
    ].join('\n');
  }

  const overall = learningGroupStatsV312(records);
  const groupLines = (title, extractor) => {
    const groups = new Map();
    for (const record of records) {
      const key = extractor(record?.entrySignalSnapshotV309, record);
      if (!key) continue;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(record);
    }
    if (!groups.size) return [];
    const lines = [`<b>${title}</b>`];
    for (const [key, items] of groups.entries()) {
      const stats = learningGroupStatsV312(items);
      lines.push(`• ${escapeHtml(String(key))}: ${learningStatsTextV312(stats)}`);
      if (stats?.n >= 2) lines.push(`  ↳ ${learningOutlierTextV313(stats)}`);
    }
    return lines;
  };

  const confidence = groupLines('🔎 Confidence at entry', snap => snap?.confidence?.label || null);
  const momentum = groupLines('🚀 Momentum at entry', snap => snap?.momentum?.label || null);
  const whaleFlow = groupLines('🐋 Whale flow at entry', snap => snap?.whaleFlow?.flow || null);
  const concentration = groupLines('👥 Concentration at entry', snap =>
    snap?.holders?.concentrationVerified === true ? (snap?.holders?.concentration || null) : null
  );
  const marketQuality = groupLines('🧪 Market Quality band', snap => {
    if (snap?.marketQuality?.verified !== true) return null;
    return learningBandV312(snap?.marketQuality?.score, [
      { min: 0, max: 24.999, label: '0–24' },
      { min: 25, max: 49.999, label: '25–49' },
      { min: 50, max: 74.999, label: '50–74' },
      { min: 75, max: 100, label: '75–100' }
    ]);
  });
  const rugRisk = groupLines('🛡 Rug Risk band', snap => {
    if (snap?.rugRisk?.verified !== true) return null;
    return learningBandV312(snap?.rugRisk?.score, [
      { min: 0, max: 24.999, label: '0–24' },
      { min: 25, max: 49.999, label: '25–49' },
      { min: 50, max: 74.999, label: '50–74' },
      { min: 75, max: 100, label: '75–100' }
    ]);
  });

  const lines = [
    '🧠 <b>Frozen Entry Learning — V317</b>',
    '',
    `Frozen calls analysed: <b>${records.length}</b> / ${all.length} tracked`,
    `Overall: <b>${learningStatsTextV312(overall)}</b>`,
    `↗️ Entry quality: went above entry <b>${overall?.wentAboveEntryV407 || 0}/${overall?.n || 0}</b> | never above entry <b>${overall?.neverAboveEntryV407 || 0}/${overall?.n || 0}</b>`,
    `📐 Outlier impact: ${learningOutlierTextV313(overall)}`,
    '',
    '<b>⏳ Outcome maturity cohorts</b>',
    learningMaturityLineV316('≥1h old', learningMaturityCohortV316(records, 60 * 60 * 1000)),
    learningMaturityLineV316('≥6h old', learningMaturityCohortV316(records, 6 * 60 * 60 * 1000)),
    learningMaturityLineV316('≥24h old', learningMaturityCohortV316(records, 24 * 60 * 60 * 1000)),
    '<i>Age cohorts reduce right-censoring: very new 1.00x calls are not treated as if they already had equal time to perform.</i>',
    '',
    '<b>🎯 Forward-only fixed-horizon outcomes — V317</b>',
    fixedHorizonLearningLineV317('1h outcome', records, 'h1'),
    fixedHorizonLearningLineV317('6h outcome', records, 'h6'),
    fixedHorizonLearningLineV317('24h outcome', records, 'h24'),
    '<i>First verified market-cap observation at/after each target is frozen. Observation lag is preserved; pre-V317 calls are never backfilled.</i>',
    '',
    ...confidence, '',
    ...momentum, '',
    ...whaleFlow, '',
    ...concentration, '',
    ...marketQuality, '',
    ...rugRisk, '',
    '📏 Sample strength: TOO_SMALL &lt;3 | VERY_SMALL 3–9 | SMALL 10–29 | BUILDING 30–99 | STRONGER 100+',
    '⚠️ <b>DESCRIPTIVE ONLY</b> — V317 does not change scoring, weights, thresholds or qualification.',
    '<i>Only frozen call-time fields are compared with later verified ATH multiples. Missing entry evidence is excluded, never backfilled.</i>'
  ];

  return lines.filter((line, index, arr) => !(line === '' && arr[index - 1] === '')).join('\n');
}

function formatUsdV353(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return "UNVERIFIED";
  const sign = n < 0 ? "-" : "";
  return `${sign}$${Math.abs(n).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

