function parseTelegramCommandV271(
  text
) {
  const raw =
    String(text || "")
      .trim();

  if (!raw.startsWith("/")) {
    return null;
  }

  const parts =
    raw.split(/\s+/);

  const command =
    String(parts.shift() || "")
      .split("@")[0]
      .toLowerCase();

  return {
    command,
    argument:
      parts.join(" ").trim()
  };
}

async function telegramAnalyseCheckpointV352(
  env,
  diagnosticV273,
  stage,
  extra = null
) {
  if (!diagnosticV273) {
    return { persisted: false, reason: "NO_DIAGNOSTIC_OBJECT" };
  }

  const startedAt =
    Number(diagnosticV273.receivedAt) ||
    Date.now();

  diagnosticV273.telegramAnalyseStageV352 =
    String(stage || "UNKNOWN");
  diagnosticV273.telegramAnalyseStageAtV352 =
    Date.now();
  diagnosticV273.telegramAnalyseElapsedMsV352 =
    Math.max(0, Date.now() - startedAt);

  if (extra && typeof extra === "object") {
    diagnosticV273.telegramAnalyseStageExtraV352 = extra;
  }

  return await persistTelegramWebhookDiagnosticV273(
    env,
    diagnosticV273
  );
}

async function telegramCommandReplyV271(
  env,
  update,
  diagnosticV273 = null
) {
  const message =
    update?.message ||
    update?.edited_message ||
    update?.channel_post ||
    update?.edited_channel_post ||
    null;

  if (diagnosticV273) {
    diagnosticV273.updateType =
      telegramUpdateTypeV273(
        update
      );

    diagnosticV273.messagePresent =
      message !== null;

    diagnosticV273.messageText =
      message?.text !==
        undefined &&
      message?.text !==
        null
        ? String(
            message.text
          )
        : null;

    diagnosticV273.chatType =
      message?.chat?.type ||
      null;

    diagnosticV273.chatTitle =
      message?.chat?.title ||
      null;

    diagnosticV273.chatUsername =
      message?.chat?.username ||
      null;
  }

  const chatId =
    message?.chat?.id !==
      undefined &&
    message?.chat?.id !==
      null
      ? String(
          message.chat.id
        )
      : null;

  const configuredChatId =
    env.TELEGRAM_CHAT_ID !==
      undefined &&
    env.TELEGRAM_CHAT_ID !==
      null
      ? String(
          env.TELEGRAM_CHAT_ID
        )
      : null;

  if (diagnosticV273) {
    diagnosticV273.receivedChatId =
      chatId;

    diagnosticV273.configuredChatId =
      configuredChatId;

    diagnosticV273.authorized =
      Boolean(
        message &&
        chatId &&
        configuredChatId &&
        chatId ===
          configuredChatId
      );
  }

  if (
    !message ||
    !chatId ||
    !configuredChatId ||
    chatId !== configuredChatId
  ) {
    if (diagnosticV273) {
      diagnosticV273.commandParsed =
        false;
      diagnosticV273.replyAttempted =
        false;
      diagnosticV273.result =
        "UNAUTHORIZED_OR_UNSUPPORTED_CHAT";
    }

    return {
      success: true,
      ignored: true,
      reason:
        "UNAUTHORIZED_OR_UNSUPPORTED_CHAT"
    };
  }

  const parsed =
    parseTelegramCommandV271(
      message?.text
    );

  if (diagnosticV273) {
    diagnosticV273.commandParsed =
      parsed !== null;
    diagnosticV273.command =
      parsed?.command ||
      null;
    diagnosticV273.argument =
      parsed?.argument ||
      null;
  }

  if (!parsed) {
    if (diagnosticV273) {
      diagnosticV273.replyAttempted =
        false;
      diagnosticV273.result =
        "NOT_A_COMMAND";
    }

    return {
      success: true,
      ignored: true,
      reason:
        "NOT_A_COMMAND"
    };
  }

  const isFreshAnalyseV352 =
    parsed.command === "/analyse" ||
    parsed.command === "/analyze";


  // V404: read-only account-wide bot-side Durable Object usage estimate.
  // Does not trigger a scanner run or external provider request.
  if (parsed.command === "/usage") {
    const usageV404 = await durableUsageSnapshotV404(env);
    const replyV404 = durableUsageTelegramMessageV404(usageV404);
    if (diagnosticV273) {
      diagnosticV273.replyAttempted = true;
      diagnosticV273.durableUsageV404 = {status:usageV404?.status||null,estimatedRowsWritten:usageV404?.estimatedRowsWritten??null,usedPct:usageV404?.usedPct??null,projected24hRows:usageV404?.projected24hRows??null,scannerBudgetConsumed:false,externalProviderRequests:0};
    }
    const resultV404 = await sendTelegram(env, replyV404, null, null);
    if (diagnosticV273) {
      diagnosticV273.replySuccess = resultV404?.success === true;
      diagnosticV273.telegramStatus = resultV404?.status || null;
      diagnosticV273.telegramMode = resultV404?.mode || null;
      diagnosticV273.telegramError = resultV404?.error || null;
      diagnosticV273.result = resultV404?.success === true ? "REPLY_SENT" : "REPLY_FAILED";
    }
    return {success:resultV404?.success===true,ignored:false,command:parsed.command,scannerBudgetConsumed:false,externalProviderRequests:0};
  }

  /* V353: isolated address-only persisted USD reader.
   * Deliberately handled before readState so it cannot enter the fresh /analyse path.
   * Reuses the already-proven V351 HTTP aggregation function: KV reads only,
   * zero KV writes and zero external provider/pricing/RPC requests.
   */
  if (parsed.command === "/v3usd") {
    let replyV353;
    if (!isAddress(normalize(parsed.argument))) {
      replyV353 = "ℹ️ Use <code>/v3usd 0xADDRESS</code>. V353 is deliberately address-only.";
    } else {
      const usdV353 = await v3UsdDiagnosticV351(env, parsed.argument);
      replyV353 = v3UsdTelegramMessageV353(usdV353);
      if (diagnosticV273) {
        diagnosticV273.v3UsdV353 = {
          status: usdV353?.status || null,
          elapsedMs: usdV353?.elapsedMs ?? null,
          ledgerRecords: usdV353?.ledgerRecords ?? null,
          usdVerifiedRecords: usdV353?.usdVerifiedRecords ?? null,
          writes: 0,
          externalRequests: 0
        };
      }
    }

    if (diagnosticV273) diagnosticV273.replyAttempted = true;
    const resultV353 = await sendTelegram(env, replyV353, null, null);
    if (diagnosticV273) {
      diagnosticV273.replySuccess = resultV353?.success === true;
      diagnosticV273.telegramStatus = resultV353?.status || null;
      diagnosticV273.telegramMode = resultV353?.mode || null;
      diagnosticV273.telegramError = resultV353?.error || null;
      diagnosticV273.result = resultV353?.success === true ? "REPLY_SENT" : "REPLY_FAILED";
    }
    return {
      success: resultV353?.success === true,
      ignored: false,
      command: parsed.command,
      argument: parsed.argument,
      telegramStatus: resultV353?.status || null,
      telegramMode: resultV353?.mode || null,
      scannerBudgetConsumed: false
    };
  }

  if (isFreshAnalyseV352) {
    await telegramAnalyseCheckpointV352(
      env,
      diagnosticV273,
      "BEFORE_READ_STATE"
    );
  }

  const loaded =
    await readState(env);

  const state =
    loaded?.state ||
    newState();

  if (isFreshAnalyseV352) {
    await telegramAnalyseCheckpointV352(
      env,
      diagnosticV273,
      "AFTER_READ_STATE"
    );
  }

  let reply;

  if (
    parsed.command ===
      "/call" ||
    parsed.command ===
      "/ath" ||
    parsed.command ===
      "/stats"
  ) {
    const resolved =
      resolveCallPerformanceV271(
        state,
        parsed.argument
      );

    if (
      resolved.status ===
      "MISSING_QUERY"
    ) {
      reply =
        "ℹ️ Use <code>/call SYMBOL</code> or <code>/call 0xADDRESS</code>.";
    } else if (
      resolved.status ===
      "AMBIGUOUS_SYMBOL"
    ) {
      reply = [
        "⚠️ <b>More than one call uses that symbol.</b>",
        "",
        "Use the contract address instead:",
        ...resolved.matches
          .slice(0, 10)
          .map(
            record =>
              `<code>${escapeHtml(
                record?.address ||
                ""
              )}</code>`
          )
      ].join("\n");
    } else if (
      resolved.record
    ) {
      reply =
        callPerformanceMessageV271(
          resolved.record
        );
    } else {
      reply =
        "❌ <b>Call not found.</b>\n\nUse <code>/calls</code> to see stored V270+ calls.";
    }
  } else if (
    parsed.command ===
    "/callinfo"
  ) {
    const resolved =
      resolveCallPerformanceV271(
        state,
        parsed.argument
      );

    if (resolved.status === "MISSING_QUERY") {
      reply = "ℹ️ Use <code>/callinfo SYMBOL</code> or <code>/callinfo 0xADDRESS</code>.";
    } else if (resolved.status === "AMBIGUOUS_SYMBOL") {
      reply = [
        "⚠️ <b>More than one call uses that symbol.</b>",
        "",
        "Use the contract address instead:",
        ...resolved.matches.slice(0, 10).map(record =>
          `<code>${escapeHtml(record?.address || "")}</code>`
        )
      ].join("\n");
    } else if (resolved.record) {
      reply = callInfoMessageV311(resolved.record);
    } else {
      reply = "❌ <b>Call not found.</b>\n\nUse <code>/calls</code> to see stored calls.";
    }
  } else if (
    parsed.command ===
    "/horizon"
  ) {
    const resolved =
      resolveCallPerformanceV271(
        state,
        parsed.argument
      );

    if (resolved.status === "MISSING_QUERY") {
      reply = "ℹ️ Use <code>/horizon SYMBOL</code> or <code>/horizon 0xADDRESS</code>.";
    } else if (resolved.status === "AMBIGUOUS_SYMBOL") {
      reply = [
        "⚠️ <b>More than one call uses that symbol.</b>",
        "",
        "Use the contract address instead:",
        ...resolved.matches.slice(0, 10).map(record =>
          `<code>${escapeHtml(record?.address || "")}</code>`
        )
      ].join("\n");
    } else if (resolved.record) {
      reply = horizonDiagnosticsMessageV318(resolved.record);
    } else {
      reply = "❌ <b>Call not found.</b>\n\nUse <code>/calls</code> to see stored calls.";
    }
  } else if (
    parsed.command ===
    "/analyse" ||
    parsed.command ===
    "/analyze"
  ) {
    await telegramAnalyseCheckpointV352(
      env,
      diagnosticV273,
      "BEFORE_FRESH_ANALYSE"
    );

    const freshStartedAtV352 = Date.now();
    const fresh =
      await telegramFreshAnalyseV276(
        env,
        state,
        parsed.argument
      );

    await telegramAnalyseCheckpointV352(
      env,
      diagnosticV273,
      "AFTER_FRESH_ANALYSE",
      {
        freshAnalyseElapsedMs:
          Date.now() - freshStartedAtV352,
        replyChars:
          String(fresh?.reply || "").length
      }
    );

    reply =
      fresh.reply;

    if (diagnosticV273) {
      diagnosticV273
        .telegramAnalyseV276 =
        fresh.telemetry;
    }
  } else if (
    parsed.command ===
    "/calls"
  ) {
    reply =
      callsListMessageV271(
        state
      );
  } else if (
    parsed.command ===
    "/best"
  ) {
    reply =
      bestCallsMessageV271(
        state
      );
  } else if (
    parsed.command ===
    "/performance"
  ) {
    reply =
      performanceSummaryV271(
        state
      );
  } else if (
    parsed.command ===
    "/learning"
  ) {
    reply =
      frozenLearningMessageV312(
        state
      );
  } else if (
    parsed.command ===
      "/help" ||
    parsed.command ===
      "/start"
  ) {
    reply =
      telegramHelpV271();
  } else {
    reply =
      telegramHelpV271();
  }

  if (diagnosticV273) {
    diagnosticV273.replyAttempted =
      true;
  }

  // V317: /learning preserves chunked delivery and escapes literal '<' text for Telegram HTML as
  // sample-quality sections grow. Reuse the already-proven V292 line-safe
  // chunked sender. Literal comparison text uses &lt; so Telegram parse_mode=HTML
  // cannot misread it as a malformed tag. Zero provider/scanner/scoring changes.
  const needsChunkedReplyV316 =
    parsed.command === "/analyse" ||
    parsed.command === "/analyze" ||
    parsed.command === "/learning";

  if (isFreshAnalyseV352) {
    await telegramAnalyseCheckpointV352(
      env,
      diagnosticV273,
      "BEFORE_TELEGRAM_SEND",
      { replyChars: String(reply || "").length }
    );
  }

  const telegramSendStartedAtV352 = Date.now();
  const result =
    needsChunkedReplyV316
      ? await sendTelegramManualReplyV292(env, reply)
      : await sendTelegram(
          env,
          reply,
          null,
          null
        );

  if (isFreshAnalyseV352) {
    await telegramAnalyseCheckpointV352(
      env,
      diagnosticV273,
      "AFTER_TELEGRAM_SEND",
      {
        telegramSendElapsedMs:
          Date.now() - telegramSendStartedAtV352,
        success: result?.success === true,
        status: result?.status || null,
        mode: result?.mode || null,
        error: result?.error || null
      }
    );
  }

  if (diagnosticV273) {
    diagnosticV273.replySuccess =
      result?.success ===
      true;

    diagnosticV273.telegramStatus =
      result?.status ||
      null;

    diagnosticV273.telegramMode =
      result?.mode ||
      null;

    diagnosticV273.telegramError =
      result?.error ||
      null;

    diagnosticV273.result =
      result?.success ===
        true
        ? "REPLY_SENT"
        : "REPLY_FAILED";
  }

  return {
    success:
      result?.success ===
      true,
    ignored:
      false,
    command:
      parsed.command,
    argument:
      parsed.argument,
    telegramStatus:
      result?.status ||
      null,
    telegramMode:
      result?.mode ||
      null,
    scannerBudgetConsumed:
      false
  };
}

async function telegramWebhookV271(
  request,
  env
) {
  const diagnosticV273 = {
    schemaVersion:
      "V273_TELEGRAM_WEBHOOK_DIAGNOSTIC_1",
    receivedAt:
      Date.now(),
    botVersion:
      VERSION,
    webhookPath:
      "/telegram-webhook",
    scannerBudgetConsumed:
      false,
    externalProviderRequestsAdded:
      0,
    updateType:
      null,
    messagePresent:
      null,
    messageText:
      null,
    receivedChatId:
      null,
    configuredChatId:
      env.TELEGRAM_CHAT_ID !==
        undefined &&
      env.TELEGRAM_CHAT_ID !==
        null
        ? String(
            env.TELEGRAM_CHAT_ID
          )
        : null,
    authorized:
      null,
    commandParsed:
      null,
    command:
      null,
    argument:
      null,
    replyAttempted:
      null,
    replySuccess:
      null,
    telegramStatus:
      null,
    telegramMode:
      null,
    telegramError:
      null,
    result:
      null
  };

  try {
    const update =
      await request.json();

    diagnosticV273.updateType =
      telegramUpdateTypeV273(
        update
      );

    const message =
      telegramMessageFromUpdateV273(
        update
      );

    diagnosticV273.messageText =
      message?.text !==
        undefined &&
      message?.text !==
        null
        ? String(
            message.text
          )
        : null;

    diagnosticV273.receivedChatId =
      message?.chat?.id !==
        undefined &&
      message?.chat?.id !==
        null
        ? String(
            message.chat.id
          )
        : null;

    const result =
      await telegramCommandReplyV271(
        env,
        update,
        diagnosticV273
      );

    diagnosticV273.commandResult =
      result;

    const persistence =
      await persistTelegramWebhookDiagnosticV273(
        env,
        diagnosticV273
      );

    return jsonResponse({
      ok: true,
      version: VERSION,
      webhook: "V273_DIAGNOSTIC",
      result,
      diagnosticPersistence:
        persistence,
      timestamp: now()
    });
  } catch (error) {
    diagnosticV273.result =
      "WEBHOOK_HANDLER_ERROR";

    diagnosticV273.error =
      errorString(error);

    await persistTelegramWebhookDiagnosticV273(
      env,
      diagnosticV273
    );

    /*
     * Telegram expects a 2xx response to avoid repeated delivery storms.
     */
    return jsonResponse({
      ok: true,
      version: VERSION,
      webhook: "V273_DIAGNOSTIC",
      handledWithError: true,
      error:
        errorString(error),
      timestamp: now()
    });
  }
}

async function telegramWebhookSetupV271(
  request,
  env
) {
  if (!env.TELEGRAM_BOT_TOKEN) {
    return {
      success: false,
      status:
        "TELEGRAM_BOT_TOKEN_NOT_CONFIGURED"
    };
  }

  const requestUrl =
    new URL(request.url);

  const webhookUrl =
    `${requestUrl.origin}/telegram-webhook`;

  const payload = {
    url:
      webhookUrl,
    allowed_updates: [
      "message",
      "edited_message",
      "channel_post",
      "edited_channel_post"
    ],
    drop_pending_updates:
      false
  };

  if (
    env.TELEGRAM_WEBHOOK_SECRET
  ) {
    payload.secret_token =
      String(
        env.TELEGRAM_WEBHOOK_SECRET
      );
  }

  const response =
    await fetch(
      `https://api.telegram.org/bot${env.TELEGRAM_BOT_TOKEN}/setWebhook`,
      {
        method: "POST",
        headers: {
          "content-type":
            "application/json"
        },
        body:
          JSON.stringify(
            payload
          )
      }
    );

  let data = null;

  try {
    data =
      await response.json();
  } catch (_) {
    data = null;
  }

  return {
    success:
      response.ok &&
      data?.ok === true,
    version:
      VERSION,
    webhookUrl,
    telegramStatus:
      response.status,
    telegramResponse:
      data,
    scannerBudgetConsumed:
      false,
    timestamp:
      now()
  };
}



