/* ============================================================
   V348 — READ-ONLY V347 STATE DIAGNOSTIC
   ============================================================
   Deliberately isolated from /analyse and scheduled execution.
   - KV reads only
   - zero KV writes
   - zero RPC/provider/API requests
   - inspects any V347 state left in the existing KV namespace
*/
const V347_REFERENCE_DIAGNOSTIC_KEY_V348 = "robinhood-meme-hunter-v347-weth-usdg-reference";

async function v347StateDiagnosticV348(env) {
  const startedAt = Date.now();
  const { kv, binding } = getKV(env);
  const out = {
    version: VERSION,
    diagnostic: "V347_PERSISTED_STATE_READ_ONLY_V348",
    safe: true,
    writes: 0,
    externalRequests: 0,
    kvBinding: binding || null,
    reference: { found: false, parseOk: false },
    registry: { found: false, parseOk: false, tokens: 0, rows: [] },
    elapsedMs: null,
    timestamp: now()
  };
  if (!kv) {
    out.status = "KV_UNAVAILABLE_V348";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  try {
    const raw = await kv.get(V347_REFERENCE_DIAGNOSTIC_KEY_V348);
    if (raw) {
      out.reference.found = true;
      try {
        const ref = JSON.parse(raw);
        const observedAt = Number(ref?.observedAt);
        out.reference = {
          found: true,
          parseOk: true,
          verified: ref?.verified === true,
          schema: ref?.schema || null,
          priceUsdGPerWeth: Number.isFinite(Number(ref?.priceUsdGPerWeth)) ? Number(ref.priceUsdGPerWeth) : null,
          source: ref?.source || null,
          observedAt: Number.isFinite(observedAt) ? observedAt : null,
          ageMs: Number.isFinite(observedAt) ? Math.max(0, Date.now() - observedAt) : null,
          weth: ref?.weth || null,
          usdg: ref?.usdg || null,
          historicalExactBlock: ref?.historicalExactBlock === true
        };
      } catch (error) {
        out.reference.parseError = String(error?.message || error).slice(0, 180);
        out.reference.rawLength = raw.length;
      }
    }
  } catch (error) {
    out.reference.readError = String(error?.message || error).slice(0, 180);
  }

  let registryRows = [];
  try {
    const raw = await kv.get(NATIVE_V3_COLLECTOR_REGISTRY_KEY_V333);
    if (raw) {
      out.registry.found = true;
      try {
        const parsed = JSON.parse(raw);
        registryRows = Array.isArray(parsed) ? parsed : [];
        out.registry.parseOk = Array.isArray(parsed);
        out.registry.tokens = registryRows.length;
      } catch (error) {
        out.registry.parseError = String(error?.message || error).slice(0, 180);
        out.registry.rawLength = raw.length;
      }
    }
  } catch (error) {
    out.registry.readError = String(error?.message || error).slice(0, 180);
  }

  for (const row of registryRows.slice(-NATIVE_V3_COLLECTOR_MAX_TOKENS_PER_RUN_V333)) {
    const token = normalize(row?.tokenAddress);
    const item = { token, pair: null, pairStatus: null, ledger: null };
    if (!isAddress(token)) {
      item.pairStatus = "TOKEN_INVALID";
      out.registry.rows.push(item);
      continue;
    }
    try {
      const pairCache = await loadVerifiedV3PairIdentityV329(env, token);
      const pair = normalize(pairCache?.record?.pairAddress);
      item.pairStatus = pairCache?.status || null;
      item.pair = isAddress(pair) ? pair : null;
      if (pairCache?.valid === true && isAddress(pair)) {
        const ledger = await loadNativeV3SwapLedgerV331(env, token, pair);
        const rows = Array.isArray(ledger?.records) ? ledger.records : [];
        let quoteReady = 0, wethQuote = 0, usdgQuote = 0, v347Usd = 0, v347WethUsd = 0, v347UsdgUsd = 0;
        for (const r of rows) {
          const q = normalize(r?.quoteTokenAddress);
          if (r?.quoteAmountVerifiedV336 === true && Number.isFinite(Number(r?.quoteAmount)) && Number(r.quoteAmount) > 0) {
            quoteReady++;
            if (q === CANONICAL_WETH_V179) wethQuote++;
            if (q === CANONICAL_USDG_V179) usdgQuote++;
          }
          if (r?.sameCycleUsdVerifiedV347 === true && Number.isFinite(Number(r?.sameCycleUsdV347)) && Number(r.sameCycleUsdV347) > 0) {
            v347Usd++;
            if (q === CANONICAL_WETH_V179) v347WethUsd++;
            if (q === CANONICAL_USDG_V179) v347UsdgUsd++;
          }
        }
        item.ledger = {
          status: ledger?.status || null,
          valid: ledger?.valid === true,
          records: rows.length,
          verifiedRanges: Array.isArray(ledger?.scannedRanges) ? ledger.scannedRanges.length : null,
          quoteReady,
          wethQuote,
          usdgQuote,
          v347UsdVerified: v347Usd,
          v347WethUsdVerified: v347WethUsd,
          v347UsdgUsdVerified: v347UsdgUsd
        };
      }
    } catch (error) {
      item.error = String(error?.message || error).slice(0, 180);
    }
    out.registry.rows.push(item);
  }

  out.status = "DIAGNOSTIC_COMPLETE_V348";
  out.elapsedMs = Date.now() - startedAt;
  return out;
}


/* ============================================================
   V351 — HTTP-ONLY PERSISTED V3 USD AGGREGATION DIAGNOSTIC
   ============================================================
   Deliberately isolated from Telegram /analyse and scheduled execution.
   - address-only query parameter: ?token=0x...
   - existing pair-cache + ledger KV reads only
   - zero KV writes
   - zero RPC/provider/API/pricing requests
   - aggregates only already-persisted V347 same-cycle USD evidence
*/
async function v3UsdDiagnosticV351(env, tokenInput) {
  const startedAt = Date.now();
  const token = normalize(tokenInput);
  const out = {
    version: VERSION,
    diagnostic: "PERSISTED_V3_USD_HTTP_ONLY_V351",
    safe: true,
    writes: 0,
    externalRequests: 0,
    token,
    pair: null,
    evidenceBasis: "V347_SAME_CYCLE_CURRENT_REFERENCE_NOT_EXACT_HISTORICAL_BLOCK",
    coverage: "PARTIAL",
    ledgerRecords: 0,
    usdVerifiedRecords: 0,
    windows: {},
    elapsedMs: null,
    timestamp: now()
  };

  if (!isAddress(token)) {
    out.status = "INVALID_TOKEN_ADDRESS_V351";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  const { kv } = getKV(env);
  if (!kv) {
    out.status = "KV_UNAVAILABLE_V351";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  try {
    const pairCache = await loadVerifiedV3PairIdentityV329(env, token);
    const pair = normalize(pairCache?.record?.pairAddress);
    out.pairStatus = pairCache?.status || null;
    if (pairCache?.valid !== true || !isAddress(pair)) {
      out.status = "VERIFIED_V3_PAIR_UNAVAILABLE_V351";
      out.elapsedMs = Date.now() - startedAt;
      return out;
    }
    out.pair = pair;

    const ledger = await loadNativeV3SwapLedgerV331(env, token, pair);
    const rows = Array.isArray(ledger?.records) ? ledger.records : [];
    out.ledgerRecords = rows.length;
    out.verifiedRanges = Array.isArray(ledger?.scannedRanges) ? ledger.scannedRanges.length : null;

    const windows = [
      ["5m", 5 * 60 * 1000],
      ["15m", 15 * 60 * 1000],
      ["1h", 60 * 60 * 1000],
      ["6h", 6 * 60 * 60 * 1000],
      ["24h", 24 * 60 * 60 * 1000]
    ];
    const nowMs = Date.now();
    const verifiedRows = [];

    for (const r of rows) {
      const usd = Number(r?.sameCycleUsdV347);
      const ts = Number(r?.blockTimestampMs);
      const side = String(r?.side || "").toUpperCase();
      if (
        r?.sameCycleUsdVerifiedV347 === true &&
        Number.isFinite(usd) && usd > 0 &&
        Number.isFinite(ts) && ts > 0 &&
        (side === "BUY" || side === "SELL")
      ) {
        verifiedRows.push({ usd, ts, side });
      }
    }

    out.usdVerifiedRecords = verifiedRows.length;

    for (const [label, ageMs] of windows) {
      let buyUsd = 0, sellUsd = 0, buys = 0, sells = 0;
      for (const r of verifiedRows) {
        if (r.ts > nowMs || nowMs - r.ts > ageMs) continue;
        if (r.side === "BUY") { buyUsd += r.usd; buys++; }
        else { sellUsd += r.usd; sells++; }
      }
      const total = buyUsd + sellUsd;
      out.windows[label] = {
        buys,
        sells,
        buyUsd: Number(buyUsd.toFixed(6)),
        sellUsd: Number(sellUsd.toFixed(6)),
        netUsd: Number((buyUsd - sellUsd).toFixed(6)),
        buyPressurePct: total > 0 ? Number(((buyUsd / total) * 100).toFixed(2)) : null
      };
    }

    out.status = verifiedRows.length > 0
      ? "PERSISTED_USD_AGGREGATION_VERIFIED_V351"
      : "PERSISTED_USD_EVIDENCE_UNAVAILABLE_V351";
  } catch (error) {
    out.status = "DIAGNOSTIC_ERROR_V351";
    out.error = String(error?.message || error).slice(0, 240);
  }

  out.elapsedMs = Date.now() - startedAt;
  return out;
}


/* ============================================================
   V355 — READ-ONLY NATIVE V3 SWAP LEDGER INSPECTOR
   ============================================================
   Evidence-only diagnostic for comparing captured swaps with known buys.
   - address-only query parameter: ?token=0x...
   - pair-cache + ledger KV reads only
   - zero KV writes
   - zero RPC/API/pricing requests
   - exposes each captured ledger record without claiming missing trades
*/
async function v3LedgerDiagnosticV355(env, tokenInput) {
  const startedAt = Date.now();
  const token = normalize(tokenInput);
  const out = {
    version: VERSION,
    diagnostic: "NATIVE_V3_LEDGER_RECORDS_READ_ONLY_V355",
    safe: true,
    writes: 0,
    externalRequests: 0,
    token,
    pair: null,
    coverage: "PARTIAL",
    verifiedRanges: null,
    ledgerRecords: 0,
    buys: 0,
    sells: 0,
    quoteReady: 0,
    usdVerified: 0,
    records: [],
    timestamp: now(),
    elapsedMs: null
  };

  if (!isAddress(token)) {
    out.status = "INVALID_TOKEN_ADDRESS_V355";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  const { kv } = getKV(env);
  if (!kv) {
    out.status = "KV_UNAVAILABLE_V355";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  try {
    const pairCache = await loadVerifiedV3PairIdentityV329(env, token);
    const pair = normalize(pairCache?.record?.pairAddress);
    out.pairStatus = pairCache?.status || null;
    if (pairCache?.valid !== true || !isAddress(pair)) {
      out.status = "VERIFIED_V3_PAIR_UNAVAILABLE_V355";
      out.elapsedMs = Date.now() - startedAt;
      return out;
    }
    out.pair = pair;

    const ledger = await loadNativeV3SwapLedgerV331(env, token, pair);
    const rows = Array.isArray(ledger?.records) ? ledger.records : [];
    out.ledgerRecords = rows.length;
    out.verifiedRanges = Array.isArray(ledger?.scannedRanges) ? ledger.scannedRanges.length : null;

    const mapped = rows.map((r) => {
      const side = String(r?.side || "").toUpperCase();
      const quoteToken = normalize(r?.quoteTokenAddress);
      const quoteAmount = Number(r?.quoteAmount);
      const usd = Number(r?.sameCycleUsdV347);
      const ts = Number(r?.blockTimestampMs);
      const quoteVerified = r?.quoteAmountVerifiedV336 === true && Number.isFinite(quoteAmount) && quoteAmount > 0;
      const usdVerified = r?.sameCycleUsdVerifiedV347 === true && Number.isFinite(usd) && usd > 0;
      if (side === "BUY") out.buys++;
      if (side === "SELL") out.sells++;
      if (quoteVerified) out.quoteReady++;
      if (usdVerified) out.usdVerified++;
      return {
        blockNumber: Number.isFinite(Number(r?.blockNumber)) ? Number(r.blockNumber) : null,
        blockTimestampMs: Number.isFinite(ts) && ts > 0 ? ts : null,
        blockTimeIso: Number.isFinite(ts) && ts > 0 ? new Date(ts).toISOString() : null,
        txHash: r?.txHash || null,
        logIndex: Number.isFinite(Number(r?.logIndex)) ? Number(r.logIndex) : null,
        side: side === "BUY" || side === "SELL" ? side : null,
        tokenAmount: Number.isFinite(Number(r?.tokenAmount)) ? Number(r.tokenAmount) : null,
        quoteTokenAddress: isAddress(quoteToken) ? quoteToken : null,
        quoteSymbol: quoteToken === CANONICAL_WETH_V179 ? "WETH" : (quoteToken === CANONICAL_USDG_V179 ? "USDG" : null),
        quoteAmount: quoteVerified ? quoteAmount : null,
        quoteVerified,
        usdValue: usdVerified ? Number(usd.toFixed(6)) : null,
        usdVerified,
        usdBasis: r?.sameCycleUsdBasisV347 || r?.sameCycleUsdSourceV347 || null,
        historicalExactBlockPrice: false,
        pool: pair,
        captureBasis: r?.captureBasis || r?.source || r?.basis || "NATIVE_V3_LEDGER_V331",
        missingUsdReason: usdVerified ? null : (quoteVerified ? "PERSISTED_USD_NOT_AVAILABLE_FOR_RECORD" : "EXACT_QUOTE_NOT_AVAILABLE_FOR_RECORD")
      };
    });

    mapped.sort((a,b) => (b.blockTimestampMs || 0) - (a.blockTimestampMs || 0) || (b.blockNumber || 0) - (a.blockNumber || 0));
    out.records = mapped;
    out.status = "NATIVE_V3_LEDGER_RECORDS_AVAILABLE_V355";
  } catch (error) {
    out.status = "DIAGNOSTIC_ERROR_V355";
    out.error = String(error?.message || error).slice(0, 240);
  }

  out.elapsedMs = Date.now() - startedAt;
  return out;
}


/* ============================================================
   V356 — ALCHEMY V3 eth_getLogs RANGE CAPABILITY DIAGNOSTIC
   ============================================================
   HTTP-only / read-only diagnostic. It does NOT modify /analyse,
   scheduled collection, scoring, alerts, ledgers, ranges or KV state.
   Purpose: measure the largest reliable contiguous Alchemy eth_getLogs
   range for one already-verified V3 pool before changing collector size.
*/
const V356_RANGE_TESTS = [10, 100, 1000, 5000, 10000];
const V356_RANGE_TIMEOUT_MS = 4500;

function v356AlchemyUrl(env) {
  const explicit = String(env?.ALCHEMY_RPC_URL || "").trim();
  if (explicit) return explicit;
  return env?.ALCHEMY_API_KEY ? `${ALCHEMY_BASE}${env.ALCHEMY_API_KEY}` : null;
}

async function v356RawAlchemyRpc(url, method, params, timeoutMs = V356_RANGE_TIMEOUT_MS) {
  const startedAt = Date.now();
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), Math.max(500, Number(timeoutMs) || V356_RANGE_TIMEOUT_MS));
  try {
    const response = await fetch(url, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ jsonrpc: "2.0", id: Date.now(), method, params }),
      signal: controller.signal
    });
    let payload = null;
    let parseError = null;
    try { payload = await response.json(); } catch (error) { parseError = String(error?.message || error); }
    const rpcError = payload?.error || null;
    return {
      ok: response.ok && !rpcError && !parseError,
      httpStatus: response.status,
      result: response.ok && !rpcError ? (payload?.result ?? null) : null,
      rpcErrorCode: Number.isFinite(Number(rpcError?.code)) ? Number(rpcError.code) : null,
      error: rpcError?.message || parseError || (!response.ok ? `HTTP_${response.status}` : null),
      elapsedMs: Date.now() - startedAt
    };
  } catch (error) {
    const name = String(error?.name || "");
    return {
      ok: false,
      httpStatus: null,
      result: null,
      rpcErrorCode: null,
      error: name === "AbortError" ? `TIMEOUT_${timeoutMs}MS` : String(error?.message || error).slice(0, 260),
      elapsedMs: Date.now() - startedAt
    };
  } finally {
    clearTimeout(timer);
  }
}

function v356BlockNumber(value) {
  try {
    if (typeof value === "string" && /^0x[0-9a-f]+$/i.test(value)) return Number(BigInt(value));
    const n = Number(value);
    return Number.isFinite(n) ? Math.trunc(n) : null;
  } catch (_) { return null; }
}

async function v3RangeCapabilityDiagnosticV356(env, tokenInput) {
  const startedAt = Date.now();
  const token = normalize(tokenInput);
  const out = {
    version: VERSION,
    diagnostic: "ALCHEMY_V3_ETH_GETLOGS_RANGE_CAPABILITY_V356",
    safe: true,
    writes: 0,
    kvWrites: 0,
    collectorMutated: false,
    analyseMutated: false,
    token,
    pair: null,
    topic: UNISWAP_V3_SWAP_TOPIC_V326,
    provider: "ALCHEMY_ONLY",
    timeoutPerRequestMs: V356_RANGE_TIMEOUT_MS,
    requestedRanges: V356_RANGE_TESTS,
    externalRequests: 0,
    headBlock: null,
    tests: [],
    timestamp: now(),
    elapsedMs: null
  };

  if (!isAddress(token)) {
    out.status = "INVALID_TOKEN_ADDRESS_V356";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  const alchemyUrl = v356AlchemyUrl(env);
  if (!alchemyUrl) {
    out.status = "ALCHEMY_NOT_CONFIGURED_V356";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  try {
    // Existing verified pair-cache read only. No write and no pair discovery RPC.
    const pairCache = await loadVerifiedV3PairIdentityV329(env, token);
    const pair = normalize(pairCache?.record?.pairAddress);
    out.pairStatus = pairCache?.status || null;
    if (pairCache?.valid !== true || !isAddress(pair)) {
      out.status = "VERIFIED_V3_PAIR_UNAVAILABLE_V356";
      out.elapsedMs = Date.now() - startedAt;
      return out;
    }
    out.pair = pair;

    const head = await v356RawAlchemyRpc(alchemyUrl, "eth_blockNumber", []);
    out.externalRequests++;
    if (!head.ok) {
      out.status = "ALCHEMY_HEAD_FAILED_V356";
      out.headRequest = { ok:false, httpStatus:head.httpStatus, error:head.error, elapsedMs:head.elapsedMs };
      out.elapsedMs = Date.now() - startedAt;
      return out;
    }
    const headBlock = v356BlockNumber(head.result);
    if (!Number.isFinite(headBlock)) {
      out.status = "ALCHEMY_HEAD_INVALID_V356";
      out.elapsedMs = Date.now() - startedAt;
      return out;
    }
    out.headBlock = headBlock;
    out.headRequest = { ok:true, httpStatus:head.httpStatus, elapsedMs:head.elapsedMs };

    for (const blocks of V356_RANGE_TESTS) {
      const fromBlock = Math.max(0, headBlock - blocks + 1);
      const toBlock = headBlock;
      const call = await v356RawAlchemyRpc(alchemyUrl, "eth_getLogs", [{
        fromBlock: `0x${fromBlock.toString(16)}`,
        toBlock: `0x${toBlock.toString(16)}`,
        address: pair,
        topics: [UNISWAP_V3_SWAP_TOPIC_V326]
      }]);
      out.externalRequests++;
      const logs = Array.isArray(call.result) ? call.result : null;
      let firstLogBlock = null, lastLogBlock = null;
      if (logs?.length) {
        const nums = logs.map(x => v356BlockNumber(x?.blockNumber)).filter(Number.isFinite);
        if (nums.length) { firstLogBlock = Math.min(...nums); lastLogBlock = Math.max(...nums); }
      }
      out.tests.push({
        blocks,
        fromBlock,
        toBlock,
        ok: call.ok && Array.isArray(logs),
        httpStatus: call.httpStatus,
        rpcErrorCode: call.rpcErrorCode,
        error: call.error,
        elapsedMs: call.elapsedMs,
        logs: logs ? logs.length : null,
        firstLogBlock,
        lastLogBlock
      });
    }

    const successful = out.tests.filter(t => t.ok).map(t => t.blocks);
    out.largestSuccessfulRange = successful.length ? Math.max(...successful) : null;
    const failed = out.tests.filter(t => !t.ok);
    out.allRangesPassed = failed.length === 0;
    out.status = successful.length
      ? "ALCHEMY_RANGE_CAPABILITY_MEASURED_V356"
      : "ALCHEMY_RANGE_TESTS_ALL_FAILED_V356";
  } catch (error) {
    out.status = "DIAGNOSTIC_ERROR_V356";
    out.error = String(error?.message || error).slice(0, 260);
  }

  out.elapsedMs = Date.now() - startedAt;
  return out;
}



/* ============================================================
   V357 — ROBINHOOD PUBLIC RPC V3 eth_getLogs RANGE CAPABILITY
   ============================================================
   HTTP-only / read-only diagnostic. It does NOT modify /analyse,
   scheduled collection, scoring, alerts, ledgers, ranges or KV state.
   Purpose: measure whether the Robinhood public RPC can provide wider
   exact V3 Swap-log ranges than the 10-block Alchemy Free-tier limit.
*/
const V357_PUBLIC_RANGE_TESTS = [10, 100, 1000, 5000, 10000, 50000];
const V357_PUBLIC_RANGE_TIMEOUT_MS = 6500;

async function v357RawPublicRpc(method, params, timeoutMs = V357_PUBLIC_RANGE_TIMEOUT_MS) {
  const startedAt = Date.now();
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), Math.max(500, Number(timeoutMs) || V357_PUBLIC_RANGE_TIMEOUT_MS));
  try {
    const response = await fetch(PUBLIC_RPC, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ jsonrpc: "2.0", id: Date.now(), method, params }),
      signal: controller.signal
    });
    let payload = null;
    let parseError = null;
    try { payload = await response.json(); } catch (error) { parseError = String(error?.message || error); }
    const rpcError = payload?.error || null;
    return {
      ok: response.ok && !rpcError && !parseError,
      httpStatus: response.status,
      result: response.ok && !rpcError ? (payload?.result ?? null) : null,
      rpcErrorCode: Number.isFinite(Number(rpcError?.code)) ? Number(rpcError.code) : null,
      error: rpcError?.message || parseError || (!response.ok ? `HTTP_${response.status}` : null),
      elapsedMs: Date.now() - startedAt
    };
  } catch (error) {
    const name = String(error?.name || "");
    return {
      ok: false,
      httpStatus: null,
      result: null,
      rpcErrorCode: null,
      error: name === "AbortError" ? `TIMEOUT_${timeoutMs}MS` : String(error?.message || error).slice(0, 300),
      elapsedMs: Date.now() - startedAt
    };
  } finally {
    clearTimeout(timer);
  }
}

async function v3PublicRangeCapabilityDiagnosticV357(env, tokenInput) {
  const startedAt = Date.now();
  const token = normalize(tokenInput);
  const out = {
    version: VERSION,
    diagnostic: "ROBINHOOD_PUBLIC_RPC_V3_ETH_GETLOGS_RANGE_CAPABILITY_V357",
    safe: true,
    writes: 0,
    kvWrites: 0,
    collectorMutated: false,
    analyseMutated: false,
    token,
    pair: null,
    topic: UNISWAP_V3_SWAP_TOPIC_V326,
    provider: "ROBINHOOD_PUBLIC_RPC_ONLY",
    rpc: PUBLIC_RPC,
    timeoutPerRequestMs: V357_PUBLIC_RANGE_TIMEOUT_MS,
    requestedRanges: V357_PUBLIC_RANGE_TESTS,
    externalRequests: 0,
    headBlock: null,
    tests: [],
    timestamp: now(),
    elapsedMs: null
  };

  if (!isAddress(token)) {
    out.status = "INVALID_TOKEN_ADDRESS_V357";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  try {
    const pairCache = await loadVerifiedV3PairIdentityV329(env, token);
    const pair = normalize(pairCache?.record?.pairAddress);
    out.pairStatus = pairCache?.status || null;
    if (pairCache?.valid !== true || !isAddress(pair)) {
      out.status = "VERIFIED_V3_PAIR_UNAVAILABLE_V357";
      out.elapsedMs = Date.now() - startedAt;
      return out;
    }
    out.pair = pair;

    const head = await v357RawPublicRpc("eth_blockNumber", []);
    out.externalRequests++;
    if (!head.ok) {
      out.status = "PUBLIC_RPC_HEAD_FAILED_V357";
      out.headRequest = { ok:false, httpStatus:head.httpStatus, rpcErrorCode:head.rpcErrorCode, error:head.error, elapsedMs:head.elapsedMs };
      out.elapsedMs = Date.now() - startedAt;
      return out;
    }

    const headBlock = v356BlockNumber(head.result);
    if (!Number.isFinite(headBlock)) {
      out.status = "PUBLIC_RPC_HEAD_INVALID_V357";
      out.elapsedMs = Date.now() - startedAt;
      return out;
    }
    out.headBlock = headBlock;
    out.headRequest = { ok:true, httpStatus:head.httpStatus, elapsedMs:head.elapsedMs };

    for (const blocks of V357_PUBLIC_RANGE_TESTS) {
      const fromBlock = Math.max(0, headBlock - blocks + 1);
      const toBlock = headBlock;
      const call = await v357RawPublicRpc("eth_getLogs", [{
        fromBlock: `0x${fromBlock.toString(16)}`,
        toBlock: `0x${toBlock.toString(16)}`,
        address: pair,
        topics: [UNISWAP_V3_SWAP_TOPIC_V326]
      }]);
      out.externalRequests++;
      const logs = Array.isArray(call.result) ? call.result : null;
      let firstLogBlock = null;
      let lastLogBlock = null;
      if (logs?.length) {
        const nums = logs.map(x => v356BlockNumber(x?.blockNumber)).filter(Number.isFinite);
        if (nums.length) {
          firstLogBlock = Math.min(...nums);
          lastLogBlock = Math.max(...nums);
        }
      }
      out.tests.push({
        blocks,
        fromBlock,
        toBlock,
        ok: call.ok && Array.isArray(logs),
        httpStatus: call.httpStatus,
        rpcErrorCode: call.rpcErrorCode,
        error: call.error,
        elapsedMs: call.elapsedMs,
        logs: logs ? logs.length : null,
        firstLogBlock,
        lastLogBlock
      });

      // Stop escalating after the first public-RPC failure. This avoids
      // hammering the endpoint with even larger ranges once a ceiling is known.
      if (!(call.ok && Array.isArray(logs))) {
        out.stoppedAfterFailure = true;
        break;
      }
    }

    const successful = out.tests.filter(t => t.ok).map(t => t.blocks);
    out.largestSuccessfulRange = successful.length ? Math.max(...successful) : null;
    out.allAttemptedRangesPassed = out.tests.length > 0 && out.tests.every(t => t.ok);
    out.testedAllRequestedRanges = out.tests.length === V357_PUBLIC_RANGE_TESTS.length;
    out.status = successful.length
      ? "PUBLIC_RPC_RANGE_CAPABILITY_MEASURED_V357"
      : "PUBLIC_RPC_RANGE_TESTS_ALL_FAILED_V357";
  } catch (error) {
    out.status = "DIAGNOSTIC_ERROR_V357";
    out.error = String(error?.message || error).slice(0, 300);
  }

  out.elapsedMs = Date.now() - startedAt;
  return out;
}



/* ============================================================
   V358 — BLOCKSCOUT INDEXED V3 LOG RANGE CAPABILITY
   ============================================================
   HTTP-only / read-only diagnostic. No KV writes and no collector,
   /analyse, scoring or Telegram mutation. This measures whether the
   existing Robinhood Blockscout indexed logs API can retrieve exact V3
   Swap logs across much wider ranges than Alchemy Free's 10-block cap.
*/
const V358_BLOCKSCOUT_RANGE_TESTS = [10000, 50000, 100000, 250000, 500000, 1000000];
const V358_BLOCKSCOUT_TIMEOUT_MS = 7000;
const V358_BLOCKSCOUT_SATURATION_ROWS = 1000;

async function v358BlockscoutLogsRequest(pair, fromBlock, toBlock) {
  const startedAt = Date.now();
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), V358_BLOCKSCOUT_TIMEOUT_MS);
  const url = `${BLOCKSCOUT}/api?module=logs&action=getLogs` +
    `&fromBlock=${Math.max(0, Math.trunc(fromBlock))}` +
    `&toBlock=${Math.max(0, Math.trunc(toBlock))}` +
    `&address=${encodeURIComponent(pair)}` +
    `&topic0=${encodeURIComponent(UNISWAP_V3_SWAP_TOPIC_V326)}`;
  try {
    const response = await fetch(url, {headers:{accept:"application/json"}, signal:controller.signal});
    let payload=null, parseError=null;
    try { payload=await response.json(); } catch(error){ parseError=String(error?.message||error); }
    let rows=[];
    if(Array.isArray(payload?.result)) rows=payload.result;
    const message=String(payload?.message||payload?.result||"");
    const noRecords=!rows.length && /no\s+(records|logs)\s+found/i.test(message);
    const payloadOk=Array.isArray(payload?.result) || noRecords;
    let firstLogBlock=null,lastLogBlock=null;
    if(rows.length){
      const blocks=rows.map(r=>rpcBlockNumberV331(r?.blockNumber)).filter(Number.isFinite);
      if(blocks.length){ firstLogBlock=Math.min(...blocks); lastLogBlock=Math.max(...blocks); }
    }
    return {
      ok:response.ok && !parseError && payloadOk,
      httpStatus:response.status,
      logs:rows.length,
      saturated:rows.length>=V358_BLOCKSCOUT_SATURATION_ROWS,
      firstLogBlock,lastLogBlock,
      error:parseError || (!response.ok?`HTTP_${response.status}`:(!payloadOk?message.slice(0,240)||"INVALID_PAYLOAD":null)),
      elapsedMs:Date.now()-startedAt
    };
  } catch(error){
    return {ok:false,httpStatus:null,logs:null,saturated:false,firstLogBlock:null,lastLogBlock:null,error:String(error?.name||"")==="AbortError"?`TIMEOUT_${V358_BLOCKSCOUT_TIMEOUT_MS}MS`:String(error?.message||error).slice(0,260),elapsedMs:Date.now()-startedAt};
  } finally { clearTimeout(timer); }
}

async function v3BlockscoutRangeCapabilityDiagnosticV358(env, tokenInput){
  const startedAt=Date.now();
  const token=normalize(tokenInput);
  const out={version:VERSION,diagnostic:"BLOCKSCOUT_INDEXED_V3_LOG_RANGE_CAPABILITY_V358",safe:true,writes:0,kvWrites:0,collectorMutated:false,analyseMutated:false,token,pair:null,topic:UNISWAP_V3_SWAP_TOPIC_V326,provider:"ROBINHOOD_BLOCKSCOUT_INDEXED_LOGS",endpoint:`${BLOCKSCOUT}/api?module=logs&action=getLogs`,timeoutPerRequestMs:V358_BLOCKSCOUT_TIMEOUT_MS,saturationRows:V358_BLOCKSCOUT_SATURATION_ROWS,requestedRanges:V358_BLOCKSCOUT_RANGE_TESTS,externalRequests:0,headBlock:null,tests:[],timestamp:now(),elapsedMs:null};
  if(!isAddress(token)){out.status="INVALID_TOKEN_ADDRESS_V358";out.elapsedMs=Date.now()-startedAt;return out;}
  try{
    const pairCache=await loadVerifiedV3PairIdentityV329(env,token);
    const pair=normalize(pairCache?.record?.pairAddress);
    out.pairStatus=pairCache?.status||null;
    if(pairCache?.valid!==true||!isAddress(pair)){out.status="VERIFIED_V3_PAIR_UNAVAILABLE_V358";out.elapsedMs=Date.now()-startedAt;return out;}
    out.pair=pair;
    // Head is obtained from Alchemy through the existing bounded RPC helper only
    // so the public RPC 429 observed in V357 cannot invalidate this test.
    const budget=createNativeV3CollectorBudgetV333();
    const head=await rpc(env,"eth_blockNumber",[],budget,"analysis");
    out.externalRequests++;
    try{if(head?.result) out.headBlock=Number(BigInt(head.result));}catch(_){}
    if(!Number.isFinite(out.headBlock)){out.status="HEAD_UNVERIFIED_V358";out.elapsedMs=Date.now()-startedAt;return out;}
    for(const blocks of V358_BLOCKSCOUT_RANGE_TESTS){
      const fromBlock=Math.max(0,out.headBlock-blocks+1);
      const call=await v358BlockscoutLogsRequest(pair,fromBlock,out.headBlock);
      out.externalRequests++;
      out.tests.push({blocks,fromBlock,toBlock:out.headBlock,ok:call.ok,httpStatus:call.httpStatus,elapsedMs:call.elapsedMs,logs:call.logs,saturated:call.saturated,firstLogBlock:call.firstLogBlock,lastLogBlock:call.lastLogBlock,error:call.error});
      if(!call.ok){out.stoppedAfterFailure=true;break;}
      if(call.saturated){out.stoppedAfterSaturation=true;break;}
    }
    const successful=out.tests.filter(t=>t.ok&&!t.saturated).map(t=>t.blocks);
    out.largestUnsaturatedSuccessfulRange=successful.length?Math.max(...successful):null;
    out.anySuccessful=out.tests.some(t=>t.ok);
    out.anySaturated=out.tests.some(t=>t.saturated);
    out.status=out.anySuccessful?"BLOCKSCOUT_INDEXED_RANGE_CAPABILITY_MEASURED_V358":"BLOCKSCOUT_INDEXED_RANGE_TESTS_FAILED_V358";
  }catch(error){out.status="DIAGNOSTIC_ERROR_V358";out.error=String(error?.message||error).slice(0,300);}
  out.elapsedMs=Date.now()-startedAt;
  return out;
}



/* ============================================================
   V359 — BLOCKSCOUT V2 POOL ACTIVITY CAPABILITY DIAGNOSTIC
   ============================================================
   Read-only capability probe against the per-instance Blockscout V2 REST API.
   This does NOT alter the collector or /analyse. It checks whether V2 can
   expose pool activity and, when a transaction hash is available, whether
   transaction logs can expose the exact V3 Swap topic without RPC getLogs.
*/
const V359_BLOCKSCOUT_V2_TIMEOUT_MS = 7000;

async function v359BlockscoutV2Get(path) {
  const startedAt = Date.now();
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), V359_BLOCKSCOUT_V2_TIMEOUT_MS);
  const url = `${BLOCKSCOUT}${path}`;
  try {
    const response = await fetch(url, {
      headers: { accept: "application/json" },
      signal: controller.signal
    });
    const text = await response.text();
    let payload = null;
    let parseError = null;
    try {
      payload = text ? JSON.parse(text) : null;
    } catch (error) {
      parseError = String(error?.message || error).slice(0, 220);
    }
    return {
      ok: response.ok && !parseError,
      httpStatus: response.status,
      payload,
      parseError,
      contentType: response.headers.get("content-type") || null,
      bodyPrefix: parseError ? String(text || "").slice(0, 140) : null,
      elapsedMs: Date.now() - startedAt,
      url
    };
  } catch (error) {
    return {
      ok: false,
      httpStatus: null,
      payload: null,
      parseError: null,
      contentType: null,
      bodyPrefix: null,
      error: String(error?.name || "") === "AbortError"
        ? `TIMEOUT_${V359_BLOCKSCOUT_V2_TIMEOUT_MS}MS`
        : String(error?.message || error).slice(0, 260),
      elapsedMs: Date.now() - startedAt,
      url
    };
  } finally {
    clearTimeout(timer);
  }
}

function v359ExtractItems(payload) {
  if (Array.isArray(payload?.items)) return payload.items;
  if (Array.isArray(payload)) return payload;
  return [];
}

function v359TxHash(row) {
  const values = [row?.hash, row?.transaction_hash, row?.transactionHash, row?.tx_hash, row?.txHash];
  for (const v of values) {
    const x = String(v || "").trim();
    if (/^0x[0-9a-fA-F]{64}$/.test(x)) return x.toLowerCase();
  }
  return null;
}

function v359LogTopic0(row) {
  if (Array.isArray(row?.topics) && row.topics.length) return String(row.topics[0] || "").toLowerCase();
  const x = row?.topic0 || row?.first_topic;
  return x ? String(x).toLowerCase() : null;
}

async function v3BlockscoutV2ActivityDiagnosticV359(env, tokenInput) {
  const startedAt = Date.now();
  const token = normalize(tokenInput);
  const out = {
    version: VERSION,
    diagnostic: "BLOCKSCOUT_V2_POOL_ACTIVITY_CAPABILITY_V359",
    safe: true,
    writes: 0,
    kvWrites: 0,
    collectorMutated: false,
    analyseMutated: false,
    token,
    pair: null,
    provider: "ROBINHOOD_BLOCKSCOUT_V2_REST",
    base: BLOCKSCOUT,
    timeoutPerRequestMs: V359_BLOCKSCOUT_V2_TIMEOUT_MS,
    externalRequests: 0,
    probes: [],
    transactionHashTested: null,
    transactionLogProbe: null,
    exactV3SwapLogsFound: 0,
    timestamp: now(),
    elapsedMs: null
  };

  if (!isAddress(token)) {
    out.status = "INVALID_TOKEN_ADDRESS_V359";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  try {
    const pairCache = await loadVerifiedV3PairIdentityV329(env, token);
    const pair = normalize(pairCache?.record?.pairAddress);
    out.pairStatus = pairCache?.status || null;
    if (pairCache?.valid !== true || !isAddress(pair)) {
      out.status = "VERIFIED_V3_PAIR_UNAVAILABLE_V359";
      out.elapsedMs = Date.now() - startedAt;
      return out;
    }
    out.pair = pair;

    const probePaths = [
      { name: "ADDRESS_TRANSACTIONS", path: `/api/v2/addresses/${pair}/transactions` },
      { name: "ADDRESS_INTERNAL_TRANSACTIONS", path: `/api/v2/addresses/${pair}/internal-transactions` },
      { name: "ADDRESS_TOKEN_TRANSFERS", path: `/api/v2/addresses/${pair}/token-transfers` }
    ];

    let candidateTxHash = null;

    for (const p of probePaths) {
      const r = await v359BlockscoutV2Get(p.path);
      out.externalRequests++;
      const items = v359ExtractItems(r.payload);
      const nextPage = r.payload?.next_page_params || null;
      const hashes = [];
      for (const item of items.slice(0, 50)) {
        const h = v359TxHash(item);
        if (h && !hashes.includes(h)) hashes.push(h);
      }
      if (!candidateTxHash && hashes.length) candidateTxHash = hashes[0];
      out.probes.push({
        name: p.name,
        path: p.path,
        ok: r.ok,
        httpStatus: r.httpStatus,
        elapsedMs: r.elapsedMs,
        items: items.length,
        hasNextPage: Boolean(nextPage),
        nextPageParams: nextPage,
        transactionHashesFound: hashes.length,
        firstTransactionHash: hashes[0] || null,
        payloadKeys: r.payload && typeof r.payload === "object" ? Object.keys(r.payload).slice(0, 20) : [],
        parseError: r.parseError,
        error: r.error || (!r.ok && !r.parseError ? `HTTP_${r.httpStatus}` : null),
        bodyPrefix: r.bodyPrefix
      });
    }

    if (candidateTxHash) {
      out.transactionHashTested = candidateTxHash;
      const logPath = `/api/v2/transactions/${candidateTxHash}/logs`;
      const r = await v359BlockscoutV2Get(logPath);
      out.externalRequests++;
      const logs = v359ExtractItems(r.payload);
      const exact = logs.filter(row => {
        const address = normalize(row?.address?.hash || row?.address_hash || row?.address || "");
        const topic0 = v359LogTopic0(row);
        return address === pair && topic0 === String(UNISWAP_V3_SWAP_TOPIC_V326).toLowerCase();
      });
      out.exactV3SwapLogsFound = exact.length;
      out.transactionLogProbe = {
        path: logPath,
        ok: r.ok,
        httpStatus: r.httpStatus,
        elapsedMs: r.elapsedMs,
        logs: logs.length,
        exactPoolV3SwapLogs: exact.length,
        hasNextPage: Boolean(r.payload?.next_page_params),
        payloadKeys: r.payload && typeof r.payload === "object" ? Object.keys(r.payload).slice(0, 20) : [],
        sampleExactSwapLog: exact.length ? {
          address: normalize(exact[0]?.address?.hash || exact[0]?.address_hash || exact[0]?.address || "") || null,
          topic0: v359LogTopic0(exact[0]),
          blockNumber: safeNumber(exact[0]?.block_number || exact[0]?.blockNumber) || null,
          transactionHash: v359TxHash(exact[0]),
          index: exact[0]?.index ?? exact[0]?.log_index ?? exact[0]?.logIndex ?? null,
          dataPresent: typeof exact[0]?.data === "string" && exact[0].data.length > 2
        } : null,
        parseError: r.parseError,
        error: r.error || (!r.ok && !r.parseError ? `HTTP_${r.httpStatus}` : null),
        bodyPrefix: r.bodyPrefix
      };
    }

    const successful = out.probes.filter(p => p.ok);
    const activityRows = successful.reduce((n, p) => n + safeNumber(p.items), 0);
    const paginated = successful.some(p => p.hasNextPage);

    out.v2Reachable = successful.length > 0;
    out.activityRowsReturned = activityRows;
    out.paginationAvailable = paginated;
    out.transactionLogsReachable = out.transactionLogProbe?.ok === true;
    out.exactSwapEventReachable = out.exactV3SwapLogsFound > 0;

    if (out.exactSwapEventReachable) {
      out.status = "BLOCKSCOUT_V2_EXACT_V3_SWAP_LOG_PATH_VERIFIED_V359";
    } else if (out.transactionLogsReachable) {
      out.status = "BLOCKSCOUT_V2_TRANSACTION_LOGS_REACHABLE_NO_SWAP_IN_TEST_TX_V359";
    } else if (out.v2Reachable && activityRows > 0) {
      out.status = "BLOCKSCOUT_V2_POOL_ACTIVITY_REACHABLE_V359";
    } else if (out.v2Reachable) {
      out.status = "BLOCKSCOUT_V2_REACHABLE_NO_POOL_ACTIVITY_ROWS_V359";
    } else {
      out.status = "BLOCKSCOUT_V2_POOL_ACTIVITY_UNAVAILABLE_V359";
    }
  } catch (error) {
    out.status = "DIAGNOSTIC_ERROR_V359";
    out.error = String(error?.message || error).slice(0, 300);
  }

  out.elapsedMs = Date.now() - startedAt;
  return out;
}


/* =========================================================
   V360 — ALCHEMY ROBINHOOD WEBSOCKET SUBSCRIPTION CAPABILITY
   Read-only capability diagnostic. No KV writes, no collector mutation.
   Proves whether the configured Alchemy Robinhood endpoint accepts an
   exact Uniswap V3 Swap log subscription for the verified token pool.
   ========================================================= */

async function v3AlchemyWebSocketDiagnosticV360(env, tokenInput) {
  const startedAt = Date.now();
  const token = normalize(tokenInput || "");
  const out = {
    version: VERSION,
    diagnostic: "ALCHEMY_ROBINHOOD_V3_WEBSOCKET_CAPABILITY_V360",
    safe: true,
    writes: 0,
    kvWrites: 0,
    collectorMutated: false,
    analyseMutated: false,
    token: token || null,
    pair: null,
    topic: UNISWAP_V3_SWAP_TOPIC_V326,
    provider: "ALCHEMY_ROBINHOOD_WEBSOCKET_ONLY",
    apiKeyConfigured: Boolean(env.ALCHEMY_API_KEY),
    websocketUrlExposed: false,
    timeoutMs: 5000,
    connectionOpened: false,
    subscriptionAccepted: false,
    subscriptionIdPresent: false,
    matchingLogObservedDuringTest: false,
    observedLog: null,
    messagesReceived: 0,
    status: "UNTESTED_V360",
    timestamp: now()
  };

  if (!/^0x[a-f0-9]{40}$/.test(token)) {
    out.status = "INVALID_TOKEN_ADDRESS_V360";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  if (!env.ALCHEMY_API_KEY) {
    out.status = "ALCHEMY_API_KEY_NOT_CONFIGURED_V360";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  try {
    const pairCache = await loadVerifiedV3PairIdentityV329(env, token);
    const pair = normalize(pairCache?.record?.pairAddress || "");
    out.pairStatus = pairCache?.status || null;

    if (!/^0x[a-f0-9]{40}$/.test(pair)) {
      out.status = "VERIFIED_V3_PAIR_NOT_AVAILABLE_V360";
      out.elapsedMs = Date.now() - startedAt;
      return out;
    }

    out.pair = pair;

    const wsUrl = `wss://robinhood-mainnet.g.alchemy.com/v2/${String(env.ALCHEMY_API_KEY)}`;
    let ws;

    try {
      ws = new WebSocket(wsUrl);
    } catch (error) {
      out.status = "WEBSOCKET_CONSTRUCTOR_FAILED_V360";
      out.error = String(error?.message || error).slice(0, 300);
      out.elapsedMs = Date.now() - startedAt;
      return out;
    }

    const result = await new Promise((resolve) => {
      let finished = false;
      let subscriptionId = null;
      const finish = (extra = {}) => {
        if (finished) return;
        finished = true;
        clearTimeout(timer);
        try { ws.close(1000, "V360 diagnostic complete"); } catch (_) {}
        resolve(extra);
      };

      const timer = setTimeout(() => {
        finish({ timeout: true });
      }, 5000);

      ws.addEventListener("open", () => {
        out.connectionOpened = true;
        try {
          ws.send(JSON.stringify({
            jsonrpc: "2.0",
            id: 360,
            method: "eth_subscribe",
            params: [
              "logs",
              {
                address: pair,
                topics: [UNISWAP_V3_SWAP_TOPIC_V326]
              }
            ]
          }));
        } catch (error) {
          finish({ sendError: String(error?.message || error).slice(0, 300) });
        }
      });

      ws.addEventListener("message", (event) => {
        out.messagesReceived += 1;
        let msg = null;
        try {
          msg = JSON.parse(typeof event.data === "string" ? event.data : "");
        } catch (_) {
          return;
        }

        if (msg?.id === 360) {
          if (typeof msg.result === "string" && msg.result.length > 2) {
            subscriptionId = msg.result;
            out.subscriptionAccepted = true;
            out.subscriptionIdPresent = true;
            // Capability is proven by the subscription acknowledgement.
            finish({ subscriptionIdLength: subscriptionId.length });
            return;
          }
          if (msg?.error) {
            finish({ rpcError: msg.error });
            return;
          }
        }

        if (msg?.method === "eth_subscription" && msg?.params?.result) {
          const log = msg.params.result;
          const address = normalize(log?.address || "");
          const topic0 = normalize(log?.topics?.[0] || "");
          if (address === pair && topic0 === normalize(UNISWAP_V3_SWAP_TOPIC_V326)) {
            out.matchingLogObservedDuringTest = true;
            out.observedLog = {
              blockNumber: log?.blockNumber || null,
              transactionHash: log?.transactionHash || null,
              logIndex: log?.logIndex || null,
              removed: log?.removed === true,
              dataPresent: typeof log?.data === "string" && log.data.length > 2
            };
            finish({ liveLog: true });
          }
        }
      });

      ws.addEventListener("error", () => {
        finish({ websocketError: "WEBSOCKET_ERROR_EVENT" });
      });

      ws.addEventListener("close", (event) => {
        if (!finished) {
          finish({
            closedBeforeResult: true,
            closeCode: event?.code ?? null,
            closeReason: event?.reason || null
          });
        }
      });
    });

    if (result?.rpcError) {
      out.rpcErrorCode = result.rpcError?.code ?? null;
      out.error = String(result.rpcError?.message || "RPC_SUBSCRIPTION_ERROR").slice(0, 300);
      out.status = "ALCHEMY_WEBSOCKET_SUBSCRIPTION_REJECTED_V360";
    } else if (result?.sendError) {
      out.error = result.sendError;
      out.status = "ALCHEMY_WEBSOCKET_SUBSCRIBE_SEND_FAILED_V360";
    } else if (result?.websocketError) {
      out.error = result.websocketError;
      out.status = "ALCHEMY_WEBSOCKET_CONNECTION_FAILED_V360";
    } else if (result?.closedBeforeResult) {
      out.closeCode = result.closeCode;
      out.closeReason = result.closeReason;
      out.status = "ALCHEMY_WEBSOCKET_CLOSED_BEFORE_ACK_V360";
    } else if (out.subscriptionAccepted) {
      out.status = "ALCHEMY_V3_LOG_SUBSCRIPTION_VERIFIED_V360";
    } else if (result?.timeout) {
      out.status = out.connectionOpened
        ? "ALCHEMY_WEBSOCKET_OPEN_NO_SUBSCRIPTION_ACK_V360"
        : "ALCHEMY_WEBSOCKET_CONNECTION_TIMEOUT_V360";
    } else {
      out.status = "ALCHEMY_WEBSOCKET_CAPABILITY_UNRESOLVED_V360";
    }
  } catch (error) {
    out.status = "DIAGNOSTIC_ERROR_V360";
    out.error = String(error?.message || error).slice(0, 300);
  }

  out.elapsedMs = Date.now() - startedAt;
  return out;
}



/* ============================================================
   V375 — EXACT TRANSACTION V3 ROUTE / POOL RECONCILIATION
   Read-only diagnostic for a known transaction hash.
   Purpose:
   - fetch the exact transaction receipt from Alchemy
   - enumerate every Uniswap V3 Swap log in that transaction
   - verify emitting pool token0/token1/fee/factory on-chain
   - compare each pool with the bot's currently monitored verified pair
   - decode candidate-token BUY/SELL direction and exact quote amount
   - determine whether a reported buy used the monitored pool, another V3 pool,
     multiple V3 pools, or no V3 Swap log at all
   No scoring changes. No KV writes. No Durable Object trade writes.
   ============================================================ */

const UNISWAP_V3_FACTORY_SELECTOR_V375 = "0xc45a0155";

function decodeUintWordV375(value) {
  const text = String(value || "").replace(/^0x/i, "");
  if (!/^[a-fA-F0-9]{64}$/.test(text)) return null;
  try {
    const n = BigInt("0x" + text);
    return n <= BigInt(Number.MAX_SAFE_INTEGER) ? Number(n) : n.toString();
  } catch (_) {
    return null;
  }
}

function isTxHashV375(value) {
  return /^0x[a-fA-F0-9]{64}$/.test(String(value || ""));
}

async function v375EthCallRaw(alchemyUrl, to, data) {
  if (!isAddress(normalize(to))) return { ok:false, result:null, error:"INVALID_TO_ADDRESS" };
  return v356RawAlchemyRpc(
    alchemyUrl,
    "eth_call",
    [{ to: normalize(to), data }, "latest"],
    4500
  );
}

async function v3ExactTxDiagnosticV375(env, tokenInput, txInput) {
  const startedAt = Date.now();
  const token = normalize(tokenInput || "");
  const txHash = String(txInput || "").toLowerCase();

  const out = {
    version: VERSION,
    diagnostic: "EXACT_TRANSACTION_V3_ROUTE_RECONCILIATION_V375",
    safe: true,
    readOnly: true,
    workersKvWrites: 0,
    durableObjectTradeWrites: 0,
    scoringMutated: false,
    token,
    txHash,
    monitoredPair: null,
    receiptFound: false,
    transactionSucceeded: null,
    blockNumber: null,
    receiptLogCount: 0,
    v3SwapLogCount: 0,
    uniqueV3Pools: 0,
    monitoredPairSwapCount: 0,
    otherV3PoolSwapCount: 0,
    candidateV3SwapCount: 0,
    candidateBuys: 0,
    candidateSells: 0,
    candidateBuyQuoteByToken: {},
    candidateSellQuoteByToken: {},
    pools: [],
    swapLogs: [],
    conclusion: "UNVERIFIED",
    timestamp: now()
  };

  if (!isAddress(token)) {
    out.status = "INVALID_TOKEN_V375";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }
  if (!isTxHashV375(txHash)) {
    out.status = "INVALID_TX_HASH_V375";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  const cfg = await v3LiveCollectorConfigV363(env, token);
  if (cfg?.ok && isAddress(cfg?.pair)) out.monitoredPair = normalize(cfg.pair);

  const alchemyUrl = v356AlchemyUrl(env);
  if (!alchemyUrl) {
    out.status = "ALCHEMY_NOT_CONFIGURED_V375";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  const receiptCall = await v356RawAlchemyRpc(
    alchemyUrl,
    "eth_getTransactionReceipt",
    [txHash],
    6000
  );

  if (!receiptCall?.ok) {
    out.status = "TX_RECEIPT_RPC_FAILED_V375";
    out.rpcError = receiptCall?.error || null;
    out.httpStatus = receiptCall?.httpStatus ?? null;
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  const receipt = receiptCall.result;
  if (!receipt || typeof receipt !== "object") {
    out.status = "TX_RECEIPT_NOT_FOUND_V375";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  out.receiptFound = true;
  out.blockNumber = rpcBlockNumberV331(receipt?.blockNumber);
  out.transactionSucceeded =
    String(receipt?.status || "").toLowerCase() === "0x1" ? true :
    String(receipt?.status || "").toLowerCase() === "0x0" ? false : null;

  const receiptLogs = Array.isArray(receipt?.logs) ? receipt.logs : [];
  out.receiptLogCount = receiptLogs.length;

  const v3Logs = receiptLogs.filter(log =>
    String(log?.topics?.[0] || "").toLowerCase() === UNISWAP_V3_SWAP_TOPIC_V326
  );
  out.v3SwapLogCount = v3Logs.length;

  const emitters = [...new Set(
    v3Logs
      .map(log => normalize(log?.address || ""))
      .filter(isAddress)
  )].slice(0, 8);

  const poolMeta = new Map();

  for (const pool of emitters) {
    const [t0r, t1r, feeR, factoryR] = await Promise.all([
      v375EthCallRaw(alchemyUrl, pool, UNISWAP_V3_TOKEN0_SELECTOR_V326),
      v375EthCallRaw(alchemyUrl, pool, UNISWAP_V3_TOKEN1_SELECTOR_V326),
      v375EthCallRaw(alchemyUrl, pool, UNISWAP_V3_FEE_SELECTOR_V328),
      v375EthCallRaw(alchemyUrl, pool, UNISWAP_V3_FACTORY_SELECTOR_V375)
    ]);

    const token0 = t0r?.ok ? decodeEthCallAddressV326(t0r.result) : null;
    const token1 = t1r?.ok ? decodeEthCallAddressV326(t1r.result) : null;
    const factory = factoryR?.ok ? decodeEthCallAddressV326(factoryR.result) : null;
    const fee = feeR?.ok ? decodeUintWordV375(feeR.result) : null;

    const candidateInPool = token0 === token || token1 === token;
    const isMonitoredPair = out.monitoredPair === pool;

    const meta = {
      pool,
      token0,
      token1,
      fee,
      factory,
      candidateInPool,
      isMonitoredPair,
      metadataVerified:
        isAddress(token0) &&
        isAddress(token1) &&
        fee !== null &&
        isAddress(factory),
      metadataErrors: {
        token0: t0r?.ok ? null : (t0r?.error || "UNVERIFIED"),
        token1: t1r?.ok ? null : (t1r?.error || "UNVERIFIED"),
        fee: feeR?.ok ? null : (feeR?.error || "UNVERIFIED"),
        factory: factoryR?.ok ? null : (factoryR?.error || "UNVERIFIED")
      }
    };

    poolMeta.set(pool, meta);
    out.pools.push(meta);
  }

  out.uniqueV3Pools = out.pools.length;

  for (const log of v3Logs) {
    const pool = normalize(log?.address || "");
    const meta = poolMeta.get(pool) || null;
    const data = String(log?.data || "").replace(/^0x/i, "");

    const amount0Raw =
      data.length >= 128 ? signedInt256V326(data.slice(0, 64)) : null;
    const amount1Raw =
      data.length >= 128 ? signedInt256V326(data.slice(64, 128)) : null;

    let side = null;
    let quoteToken = null;
    let quoteAmount = null;
    let candidateRaw = null;
    let quoteRaw = null;

    if (meta?.candidateInPool && typeof amount0Raw === "bigint" && typeof amount1Raw === "bigint") {
      candidateRaw = meta.token0 === token ? amount0Raw : amount1Raw;
      quoteRaw = meta.token0 === token ? amount1Raw : amount0Raw;
      quoteToken = meta.token0 === token ? meta.token1 : meta.token0;

      if (candidateRaw !== 0n) side = candidateRaw < 0n ? "BUY" : "SELL";

      const quoteDecimals =
        quoteToken === CANONICAL_WETH_V179 ? 18 :
        quoteToken === CANONICAL_USDG_V179 ? CANONICAL_USDG_DECIMALS_V179 :
        null;

      if (Number.isInteger(quoteDecimals)) {
        const q = decimalFromSignedRawV326(quoteRaw, quoteDecimals);
        if (Number.isFinite(q)) quoteAmount = Math.abs(q);
      }
    }

    const row = {
      transactionHash: String(log?.transactionHash || txHash).toLowerCase(),
      logIndex: String(log?.logIndex ?? ""),
      blockNumber: rpcBlockNumberV331(log?.blockNumber),
      pool,
      isMonitoredPair: meta?.isMonitoredPair === true,
      candidateInPool: meta?.candidateInPool === true,
      token0: meta?.token0 || null,
      token1: meta?.token1 || null,
      fee: meta?.fee ?? null,
      factory: meta?.factory || null,
      side,
      quoteToken,
      quoteSymbol:
        quoteToken === CANONICAL_WETH_V179 ? "WETH" :
        quoteToken === CANONICAL_USDG_V179 ? "USDG" :
        null,
      quoteAmount,
      amount0Raw: typeof amount0Raw === "bigint" ? amount0Raw.toString() : null,
      amount1Raw: typeof amount1Raw === "bigint" ? amount1Raw.toString() : null
    };

    out.swapLogs.push(row);

    if (row.isMonitoredPair) out.monitoredPairSwapCount++;
    else out.otherV3PoolSwapCount++;

    if (row.candidateInPool) {
      out.candidateV3SwapCount++;
      if (side === "BUY") out.candidateBuys++;
      if (side === "SELL") out.candidateSells++;

      if (Number.isFinite(quoteAmount) && quoteToken) {
        const target =
          side === "BUY" ? out.candidateBuyQuoteByToken :
          side === "SELL" ? out.candidateSellQuoteByToken :
          null;
        if (target) {
          target[quoteToken] = Number(
            ((Number(target[quoteToken]) || 0) + quoteAmount).toFixed(12)
          );
        }
      }
    }
  }

  if (out.v3SwapLogCount === 0) {
    out.status = "NO_V3_SWAP_LOGS_IN_TRANSACTION_V375";
    out.conclusion = "NO_UNISWAP_V3_SWAP_TOPIC_FOUND";
  } else if (out.candidateV3SwapCount === 0) {
    out.status = "V3_SWAPS_FOUND_BUT_NOT_FOR_CANDIDATE_V375";
    out.conclusion = "V3_ACTIVITY_EXISTS_BUT_CANDIDATE_NOT_IN_VERIFIED_EMITTING_POOLS";
  } else {
    const candidateRows = out.swapLogs.filter(r => r.candidateInPool);
    const monitoredCandidateRows = candidateRows.filter(r => r.isMonitoredPair);
    const otherCandidateRows = candidateRows.filter(r => !r.isMonitoredPair);

    if (monitoredCandidateRows.length > 0 && otherCandidateRows.length === 0) {
      out.status = "CANDIDATE_SWAP_USED_MONITORED_PAIR_V375";
      out.conclusion =
        out.candidateBuys > 0
          ? "REPORTED_BUY_EXECUTED_IN_MONITORED_V3_PAIR"
          : out.candidateSells > 0
            ? "CANDIDATE_SWAP_EXECUTED_IN_MONITORED_V3_PAIR"
            : "MONITORED_PAIR_SWAP_DIRECTION_UNVERIFIED";
    } else if (monitoredCandidateRows.length === 0 && otherCandidateRows.length > 0) {
      out.status = "CANDIDATE_SWAP_USED_OTHER_V3_POOL_V375";
      out.conclusion = "ADDITIONAL_CANDIDATE_V3_POOL_NOT_CURRENTLY_MONITORED";
    } else {
      out.status = "CANDIDATE_SWAP_USED_MULTIPLE_V3_POOLS_V375";
      out.conclusion = "MULTI_POOL_V3_ROUTE_INCLUDING_MONITORED_AND_OTHER_POOL";
    }
  }

  out.elapsedMs = Date.now() - startedAt;
  return out;
}


/* ============================================================
   V374 — LIVE V3 WEBSOCKET vs DIRECT eth_getLogs RECONCILIATION
   Read-only diagnostic. No scoring mutation, no KV writes, no DO trade writes.
   Uses Alchemy's proven free-tier 10-block eth_getLogs limit.
   ============================================================ */

async function v3ReconcileDiagnosticV374(env, tokenInput, requestedBlocks=40) {
  const startedAt = Date.now();
  const token = normalize(tokenInput || "");
  const blocks = Math.max(10, Math.min(100, Math.trunc(Number(requestedBlocks) || 40)));
  const out = {
    version: VERSION,
    diagnostic: "V3_LIVE_VS_DIRECT_GETLOGS_RECONCILIATION_V374",
    safe: true,
    readOnly: true,
    workersKvWrites: 0,
    durableObjectTradeWrites: 0,
    scoringMutated: false,
    token,
    requestedBlocks: blocks,
    providerChunkSize: 10,
    pair: null,
    headBlock: null,
    fromBlock: null,
    toBlock: null,
    directLogs: 0,
    liveStoredLogs: 0,
    matched: 0,
    missedByLiveCollector: 0,
    liveOnly: 0,
    directBuys: 0,
    directSells: 0,
    directBuyQuote: 0,
    directSellQuote: 0,
    liveBuys: 0,
    liveSells: 0,
    chunks: [],
    missingExamples: [],
    timestamp: now()
  };

  if (!isAddress(token)) {
    out.status = "INVALID_TOKEN_V374";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  const cfg = await v3LiveCollectorConfigV363(env, token);
  if (!cfg?.ok) {
    out.status = cfg?.status || "LIVE_CONFIG_UNAVAILABLE_V374";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }
  out.pair = cfg.pair;

  const alchemyUrl = v356AlchemyUrl(env);
  if (!alchemyUrl) {
    out.status = "ALCHEMY_NOT_CONFIGURED_V374";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  const headCall = await v356RawAlchemyRpc(alchemyUrl, "eth_blockNumber", [], 4500);
  const head = v356BlockNumber(headCall?.result);
  if (!headCall?.ok || !Number.isFinite(head)) {
    out.status = "HEAD_UNAVAILABLE_V374";
    out.headError = headCall?.error || null;
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }

  const toBlock = head;
  const fromBlock = Math.max(0, toBlock - blocks + 1);
  out.headBlock = head;
  out.fromBlock = fromBlock;
  out.toBlock = toBlock;

  const direct = [];
  for (let from = fromBlock; from <= toBlock; from += 10) {
    const to = Math.min(toBlock, from + 9);
    const call = await v356RawAlchemyRpc(alchemyUrl, "eth_getLogs", [{
      fromBlock: "0x" + from.toString(16),
      toBlock: "0x" + to.toString(16),
      address: cfg.pair,
      topics: [UNISWAP_V3_SWAP_TOPIC_V326]
    }], 4500);
    const rows = call?.ok && Array.isArray(call.result) ? call.result : [];
    out.chunks.push({
      fromBlock: from,
      toBlock: to,
      ok: call?.ok === true,
      httpStatus: call?.httpStatus ?? null,
      rpcErrorCode: call?.rpcErrorCode ?? null,
      error: call?.error || null,
      logs: rows.length
    });
    if (!call?.ok) {
      out.status = "DIRECT_GETLOGS_CHUNK_FAILED_V374";
      out.elapsedMs = Date.now() - startedAt;
      return out;
    }
    direct.push(...rows);
  }

  // Ask the existing DO for only already-stored live rows in this exact block range.
  const ns = env?.[V3_LIVE_DO_BINDING_V363];
  if (!ns || typeof ns.idFromName !== "function" || typeof ns.get !== "function") {
    out.status = "DURABLE_OBJECT_BINDING_REQUIRED_V374";
    out.elapsedMs = Date.now() - startedAt;
    return out;
  }
  const stub = ns.get(ns.idFromName(token));
  const u = new URL("https://v3-live.internal/reconcile-v374");
  u.searchParams.set("fromBlock", String(fromBlock));
  u.searchParams.set("toBlock", String(toBlock));
  const rr = await stub.fetch(u.toString());
  const livePayload = await rr.json();
  const liveRows = Array.isArray(livePayload?.rows) ? livePayload.rows : [];

  const keyOf = (r) => `${String(r?.transactionHash || "").toLowerCase()}|${String(r?.logIndex ?? "")}`;
  const directMap = new Map();
  for (const log of direct) {
    const key = keyOf(log);
    const data = String(log?.data || "").replace(/^0x/i, "");
    const a0 = data.length >= 128 ? signedInt256V326(data.slice(0,64)) : null;
    const a1 = data.length >= 128 ? signedInt256V326(data.slice(64,128)) : null;
    const raw = cfg.token === cfg.token0 ? a0 : (cfg.token === cfg.token1 ? a1 : null);
    const quoteRaw = cfg.token === cfg.token0 ? a1 : a0;
    const quoteToken = cfg.token === cfg.token0 ? cfg.token1 : cfg.token0;
    const quoteDecimals = quoteToken === CANONICAL_WETH_V179 ? 18 : (quoteToken === CANONICAL_USDG_V179 ? CANONICAL_USDG_DECIMALS_V179 : null);
    const quote = Number.isInteger(quoteDecimals) && typeof quoteRaw === "bigint" ? decimalFromSignedRawV326(quoteRaw, quoteDecimals) : null;
    const side = typeof raw === "bigint" && raw !== 0n ? (raw < 0n ? "BUY" : "SELL") : null;
    const row = {
      tradeKey: key,
      transactionHash: String(log?.transactionHash || "").toLowerCase(),
      logIndex: String(log?.logIndex ?? ""),
      blockNumber: rpcBlockNumberV331(log?.blockNumber),
      side,
      quoteTokenAddress: quoteToken,
      quoteAmount: Number.isFinite(quote) ? Math.abs(quote) : null
    };
    directMap.set(key, row);
    if (side === "BUY") { out.directBuys++; if (Number.isFinite(row.quoteAmount)) out.directBuyQuote += row.quoteAmount; }
    if (side === "SELL") { out.directSells++; if (Number.isFinite(row.quoteAmount)) out.directSellQuote += row.quoteAmount; }
  }

  const liveMap = new Map(liveRows.map(r => [String(r.tradeKey || keyOf(r)), r]));
  for (const r of liveRows) {
    if (r?.side === "BUY") out.liveBuys++;
    if (r?.side === "SELL") out.liveSells++;
  }

  const missing = [...directMap.entries()].filter(([k]) => !liveMap.has(k)).map(([,v]) => v);
  const liveOnly = [...liveMap.keys()].filter(k => !directMap.has(k));

  out.directLogs = directMap.size;
  out.liveStoredLogs = liveMap.size;
  out.matched = directMap.size - missing.length;
  out.missedByLiveCollector = missing.length;
  out.liveOnly = liveOnly.length;
  out.capturePct = directMap.size > 0 ? Number(((out.matched / directMap.size) * 100).toFixed(2)) : 100;
  out.directBuyQuote = Number(out.directBuyQuote.toFixed(12));
  out.directSellQuote = Number(out.directSellQuote.toFixed(12));
  out.missingExamples = missing.slice(0, 12);
  out.status = missing.length === 0
    ? "DIRECT_SAMPLE_FULLY_CAPTURED_V374"
    : "LIVE_COLLECTOR_MISSED_DIRECT_LOGS_V374";
  out.interpretation = missing.length === 0
    ? "No missed Swap logs in this sampled exact-pool range. Repeat samples are needed before claiming continuous completeness."
    : "Direct eth_getLogs found exact-pool Swap logs absent from Durable Object live storage. Live totals are incomplete for this sampled range.";
  out.elapsedMs = Date.now() - startedAt;
  return out;
}

/* =========================================================
   ROUTER
   ========================================================= */


// -----------------------------------------------------------------------------
// V388 — persistent factory-verified V3 candidate-pool registry
// Additive only. Discovery remains authoritative for admission.
// Registry persistence never changes scoring or the live collector.
// -----------------------------------------------------------------------------
const V388_POOL_REGISTRY_PREFIX = "robinhood-meme-hunter-v388-v3-pool-registry:";

function v388PoolRegistryKey(token) {
  return V388_POOL_REGISTRY_PREFIX + normalize(token || "");
}

async function v388ReadPoolRegistry(env, token) {
  const { kv, binding } = getKV(env);
  if (!kv || !isAddress(token)) {
    return {
      available: !!kv,
      binding: binding || null,
      entries: [],
      readError: kv ? "INVALID_TOKEN" : "KV_UNAVAILABLE"
    };
  }
  try {
    const raw = await kv.get(v388PoolRegistryKey(token));
    if (!raw) return { available: true, binding, entries: [], readError: null };
    const parsed = JSON.parse(raw);
    const entries = Array.isArray(parsed?.entries) ? parsed.entries : [];
    return { available: true, binding, entries, readError: null };
  } catch (e) {
    return {
      available: true,
      binding,
      entries: [],
      readError: String(e?.message || e || "UNKNOWN_ERROR")
    };
  }
}


function v390RegistryComparable(entries) {
  // V391: compare only durable registry identity/verification and non-inflating
  // evidence high-water marks. Re-running an overlapping retained sample must
  // not force a KV write merely because time/pass/sample fields changed.
  return (Array.isArray(entries) ? entries : []).map(e => ({
    pool: normalize(e?.pool || ""),
    token0: normalize(e?.token0 || ""),
    token1: normalize(e?.token1 || ""),
    quoteToken: normalize(e?.quoteToken || ""),
    quoteSymbol: e?.quoteSymbol || "UNVERIFIED",
    fee: e?.fee ?? null,
    factory: normalize(e?.factory || ""),
    factoryVerified: e?.factoryVerified === true,
    candidateToken: normalize(e?.candidateToken || ""),
    isMonitoredPair: !!e?.isMonitoredPair,
    firstObservedAt: Number(e?.firstObservedAt || 0),
    observedTransactionsTotal: Number(e?.observedTransactionsTotal || 0),
    observedSwapLogsTotal: Number(e?.observedSwapLogsTotal || 0)
  })).sort((a,b) => String(a.pool).localeCompare(String(b.pool)));
}

function v390RegistryMeaningfullyChanged(beforeEntries, afterEntries) {
  try {
    return JSON.stringify(v390RegistryComparable(beforeEntries)) !==
           JSON.stringify(v390RegistryComparable(afterEntries));
  } catch {
    return true;
  }
}


// -----------------------------------------------------------------------------
// V393 — registry-driven multi-pool live-subscription PLAN (read-only shadow)
// No WebSocket mutation, no collector mutation, no scoring mutation.
// Uses only persisted factory-verified candidate pools admitted by V388+.
// -----------------------------------------------------------------------------
async function v393MultiPoolSubscriptionPlan(env, tokenInput) {
  const token = normalize(tokenInput || "");
  if (!isAddress(token)) {
    return {
      version: VERSION,
      diagnostic: "V3_MULTI_POOL_SUBSCRIPTION_PLAN_V393",
      safe: true,
      readOnly: true,
      token: token || null,
      status: "INVALID_TOKEN_V393"
    };
  }

  const registry = await v388ReadPoolRegistry(env, token);
  const eligible = (Array.isArray(registry?.entries) ? registry.entries : [])
    .filter(e => {
      const pool = normalize(e?.pool || "");
      const token0 = normalize(e?.token0 || "");
      const token1 = normalize(e?.token1 || "");
      const factory = normalize(e?.factory || "");
      return isAddress(pool) &&
        e?.factoryVerified === true &&
        normalize(e?.candidateToken || "") === token &&
        (token0 === token || token1 === token) &&
        factory === normalize(UNISWAP_V3_FACTORY_V195);
    })
    .map(e => ({
      pool: normalize(e.pool),
      token0: normalize(e.token0 || ""),
      token1: normalize(e.token1 || ""),
      quoteToken: normalize(e.quoteToken || ""),
      quoteSymbol: e?.quoteSymbol || "UNVERIFIED",
      fee: e?.fee ?? null,
      factory: normalize(e.factory || ""),
      factoryVerified: true,
      candidateToken: token,
      isMonitoredPair: e?.isMonitoredPair === true,
      registryStatus: e?.registryStatus || null,
      activityCountersTrustedForFlow: false
    }))
    .sort((a,b) =>
      Number(b.isMonitoredPair) - Number(a.isMonitoredPair) ||
      String(a.pool).localeCompare(String(b.pool))
    );

  const addresses = [...new Set(eligible.map(e => e.pool))];
  const supportedQuotes = eligible.filter(e =>
    e.quoteToken === normalize(CANONICAL_WETH_V179) ||
    e.quoteToken === normalize(CANONICAL_USDG_V179)
  );
  const unsupportedQuotes = eligible.filter(e =>
    e.quoteToken !== normalize(CANONICAL_WETH_V179) &&
    e.quoteToken !== normalize(CANONICAL_USDG_V179)
  );

  return {
    version: VERSION,
    diagnostic: "V3_MULTI_POOL_SUBSCRIPTION_PLAN_V393",
    safe: true,
    readOnly: true,
    workersKvWrites: 0,
    durableObjectWrites: 0,
    scoringMutated: false,
    collectorMutated: false,
    liveSubscriptionMutated: false,
    token,
    registry: {
      binding: registry?.binding || null,
      readError: registry?.readError || null,
      persistedEntries: Array.isArray(registry?.entries) ? registry.entries.length : 0,
      eligibleFactoryVerifiedCandidatePools: eligible.length
    },
    proposedSubscription: {
      method: "eth_subscribe",
      type: "logs",
      addressMode: "ADDRESS_ARRAY_SINGLE_LOG_SUBSCRIPTION_V393",
      addresses,
      addressCount: addresses.length,
      topics: [UNISWAP_V3_SWAP_TOPIC_V326],
      headSubscriptionPreserved: true,
      oneLogSubscriptionPlanned: true,
      applied: false
    },
    pools: eligible,
    quoteSupport: {
      supportedPoolCount: supportedQuotes.length,
      unsupportedPoolCount: unsupportedQuotes.length,
      supportedQuotes: ["WETH", "USDG"],
      unsupportedPools: unsupportedQuotes.map(e => ({
        pool: e.pool,
        quoteToken: e.quoteToken || null,
        quoteSymbol: e.quoteSymbol || "UNVERIFIED"
      }))
    },
    coverageDesignV393: {
      existingSinglePoolCoverageInheritedByNewPools: false,
      perPoolCoverageRequiredBeforeFull: true,
      tokenAggregateFullRequiresAllIncludedPoolsFull: true,
      newlyAddedPoolStartsPartial: true,
      currentCollectorCoverageUntouched: true
    },
    dedupeDesignV393: {
      swapIdentity: "TRANSACTION_HASH_PLUS_LOG_INDEX",
      routeIdentity: "TRANSACTION_HASH",
      preserveEveryPoolSwapLog: true,
      tokenLevelTransactionDedupRequired: true,
      legacyRegistryCountersUsedForFlow: false
    },
    safetyGateV393: {
      registryUsedForMembershipOnly: true,
      scoringEnabled: false,
      liveFlowScoringEnabled: false,
      subscriptionMutationEnabled: false,
      nextGate: "VALIDATE_PLAN_THEN_ENABLE_SHADOW_MULTI_POOL_SUBSCRIPTION"
    },
    status: addresses.length >= 2
      ? "MULTI_POOL_SUBSCRIPTION_PLAN_READY_V393"
      : addresses.length === 1
        ? "SINGLE_POOL_REGISTRY_PLAN_ONLY_V393"
        : "NO_VERIFIED_REGISTRY_POOLS_V393",
    timestamp: now()
  };
}

async function v388MergeVerifiedPoolRegistry(env, token, observedPools) {
  const now = Date.now();
  const { kv, binding } = getKV(env);
  const before = await v388ReadPoolRegistry(env, token);
  const map = new Map();

  for (const old of before.entries || []) {
    const pool = normalize(old?.pool || "");
    if (!isAddress(pool)) continue;
    if (old?.factoryVerified !== true) continue;
    if (normalize(old?.candidateToken || "") !== normalize(token)) continue;
    map.set(pool, {
      ...old,
      pool,
      observedInCurrentSampleV390: false,
      registryStatus: "VERIFIED_REMEMBERED_POOL_V390"
    });
  }

  let newlyAdded = 0;
  let refreshed = 0;
  for (const p of Array.isArray(observedPools) ? observedPools : []) {
    const pool = normalize(p?.pool || "");
    const token0 = normalize(p?.token0 || "");
    const token1 = normalize(p?.token1 || "");
    if (!isAddress(pool) || p?.factoryVerified !== true) continue;
    if (token0 !== normalize(token) && token1 !== normalize(token)) continue;

    const prev = map.get(pool);
    if (!prev) newlyAdded++;
    else refreshed++;

    const observedTx = Number(p?.observedTransactions || 0);
    const observedLogs = Number(p?.observedSwapLogs || 0);
    map.set(pool, {
      ...(prev || {}),
      pool,
      token0,
      token1,
      quoteToken: normalize(p?.quoteToken || prev?.quoteToken || ""),
      quoteSymbol: p?.quoteSymbol || prev?.quoteSymbol || "UNVERIFIED",
      fee: p?.fee ?? prev?.fee ?? null,
      factory: normalize(p?.factory || prev?.factory || ""),
      factoryVerified: true,
      candidateToken: normalize(token),
      isMonitoredPair: !!p?.isMonitoredPair || !!prev?.isMonitoredPair,
      firstObservedAt: prev?.firstObservedAt || now,
      lastObservedAt: now,
      observationPasses: Number(prev?.observationPasses || 0) + 1,
      observedTransactionsTotal: Math.max(Number(prev?.observedTransactionsTotal || 0), observedTx),
      observedSwapLogsTotal: Math.max(Number(prev?.observedSwapLogsTotal || 0), observedLogs),
      lastSampleObservedTransactions: observedTx,
      lastSampleObservedSwapLogs: observedLogs,
      observedInCurrentSampleV390: true,
      registryStatus: "VERIFIED_OBSERVED_AND_PERSISTED_POOL_V390"
    });
  }

  const entries = [...map.values()].sort((a,b) =>
    Number(b.isMonitoredPair) - Number(a.isMonitoredPair) ||
    Number(b.lastObservedAt || 0) - Number(a.lastObservedAt || 0) ||
    String(a.pool).localeCompare(String(b.pool))
  );

  const meaningfulChangeV390 = v390RegistryMeaningfullyChanged(before.entries, entries);
  let writeAttempted = false, writeSuccess = false, writeError = null, writeSkippedReasonV390 = null;

  if (!kv) {
    writeSkippedReasonV390 = "KV_UNAVAILABLE";
  } else if (!isAddress(token)) {
    writeSkippedReasonV390 = "INVALID_TOKEN";
  } else if (!entries.length) {
    writeSkippedReasonV390 = "NO_ELIGIBLE_REGISTRY_ENTRIES";
  } else if (!meaningfulChangeV390) {
    writeSkippedReasonV390 = "NO_MEANINGFUL_CHANGE";
  } else {
    writeAttempted = true;
    try {
      await kv.put(v388PoolRegistryKey(token), JSON.stringify({
        schemaVersion: "V391",
        token: normalize(token),
        updatedAt: now,
        entries
      }));
      writeSuccess = true;
    } catch (e) {
      writeError = String(e?.message || e || "UNKNOWN_ERROR");
    }
  }

  return {
    schemaVersion: "V391",
    key: v388PoolRegistryKey(token),
    binding: binding || before.binding || null,
    readError: before.readError,
    previousEntries: before.entries.length,
    observedEligiblePools: Array.isArray(observedPools) ? observedPools.length : 0,
    newlyAdded,
    refreshed,
    entries,
    meaningfulChangeV390,
    writeAttempted,
    writeSuccess,
    writeSkippedReasonV390,
    writeError,
    scoringMutated: false,
    collectorMutated: false
  };
}

async function handleRequest(
  request,
  env
) {
  const url =
    new URL(
      request.url
    );

  const path =
    url.pathname
      .replace(
        /\/+$/,
        ""
      ) ||
    "/";

  if (
    request.method ===
    "OPTIONS"
  ) {
    return new Response(
      null,
      {
        status:
          204,

        headers: {
          "access-control-allow-origin":
            "*",

          "access-control-allow-methods":
            "GET, POST, OPTIONS",

          "access-control-allow-headers":
            "content-type"
        }
      }
    );
  }

  if (
    path ===
      "/telegram-webhook" &&
    request.method ===
      "POST"
  ) {
    if (
      env.TELEGRAM_WEBHOOK_SECRET &&
      request.headers.get(
        "x-telegram-bot-api-secret-token"
      ) !==
        String(
          env.TELEGRAM_WEBHOOK_SECRET
        )
    ) {
      return jsonResponse(
        {
          ok: true,
          version: VERSION,
          ignored: true,
          reason:
            "WEBHOOK_SECRET_MISMATCH",
          timestamp: now()
        }
      );
    }

    return await telegramWebhookV271(
      request,
      env
    );
  }

  if (
    request.method !==
    "GET"
  ) {
    return jsonResponse(
      {
        agent:
          "Robinhood Chain Meme Hunter",

        version:
          VERSION,

        success:
          false,

        error:
          "METHOD_NOT_ALLOWED",

        timestamp:
          now()
      },

      405
    );
  }

  if (
    path ===
      "/" ||
    path ===
      "/health"
  ) {
    return jsonResponse(
      await health(
        env
      )
    );
  }

  if (path === "/usage" || path === "/durable-usage-v404") {
    return jsonResponse(await durableUsageSnapshotV404(env));
  }

  if (
    path ===
    "/v347-diagnostic"
  ) {
    return jsonResponse(
      await v347StateDiagnosticV348(
        env
      )
    );
  }

  if (
    path ===
    "/v3usd-diagnostic"
  ) {
    return jsonResponse(
      await v3UsdDiagnosticV351(
        env,
        url.searchParams.get("token") || ""
      )
    );
  }

  if (
    path ===
    "/v3ledger-diagnostic"
  ) {
    return jsonResponse(
      await v3LedgerDiagnosticV355(
        env,
        url.searchParams.get("token") || ""
      )
    );
  }

  if (
    path ===
    "/v3range-diagnostic"
  ) {
    return jsonResponse(
      await v3RangeCapabilityDiagnosticV356(
        env,
        url.searchParams.get("token") || ""
      )
    );
  }

  if (
    path ===
    "/v3public-range-diagnostic"
  ) {
    return jsonResponse(
      await v3PublicRangeCapabilityDiagnosticV357(
        env,
        url.searchParams.get("token") || ""
      )
    );
  }


  if (
    path ===
    "/v3blockscout-range-diagnostic"
  ) {
    return jsonResponse(
      await v3BlockscoutRangeCapabilityDiagnosticV358(
        env,
        url.searchParams.get("token") || ""
      )
    );
  }

  if (
    path ===
    "/v3blockscout-v2-diagnostic"
  ) {
    return jsonResponse(
      await v3BlockscoutV2ActivityDiagnosticV359(
        env,
        url.searchParams.get("token") || ""
      )
    );
  }


  if (
    path ===
    "/v3websocket-diagnostic"
  ) {
    return jsonResponse(
      await v3AlchemyWebSocketDiagnosticV360(
        env,
        url.searchParams.get("token") || ""
      )
    );
  }






  if (path === "/v3multipool-diagnostic") {
    const token = normalize(url.searchParams.get("token") || "");
    const requestedMaxTx = Number(url.searchParams.get("maxTx") || 12);
    const maxTx = Math.max(1, Math.min(20, Number.isFinite(requestedMaxTx) ? Math.floor(requestedMaxTx) : 12));

    if (!isAddress(token)) {
      return jsonResponse({
        version: VERSION,
        diagnostic: "V3_CANDIDATE_MULTI_POOL_DISCOVERY_V379",
        safe: true,
        readOnly: true,
        status: "INVALID_TOKEN_V379"
      }, 400);
    }

    if (!env?.V3_LIVE_COLLECTOR) {
      return jsonResponse({
        version: VERSION,
        diagnostic: "V3_CANDIDATE_MULTI_POOL_DISCOVERY_V379",
        safe: true,
        readOnly: true,
        status: "V3_LIVE_COLLECTOR_BINDING_UNAVAILABLE_V379"
      }, 503);
    }

    const cfg = await v3LiveCollectorConfigV363(env, token);
    const monitoredPair = cfg?.ok && isAddress(cfg?.pair) ? normalize(cfg.pair) : null;
    const alchemyUrl = v356AlchemyUrl(env);

    if (!alchemyUrl) {
      return jsonResponse({
        version: VERSION,
        diagnostic: "V3_CANDIDATE_MULTI_POOL_DISCOVERY_V379",
        safe: true,
        readOnly: true,
        token,
        monitoredPair,
        status: "ALCHEMY_NOT_CONFIGURED_V379"
      }, 503);
    }

    const id = env.V3_LIVE_COLLECTOR.idFromName(token);
    const stub = env.V3_LIVE_COLLECTOR.get(id);

    // Read retained raw rows through the proven V378 audit path.
    let rawAudit;
    try {
      const r = await stub.fetch(
        "https://v3-live.internal/aggregation-audit-v378?now=" + Date.now()
      );
      rawAudit = await r.json();
    } catch (e) {
      return jsonResponse({
        version: VERSION,
        diagnostic: "V3_CANDIDATE_MULTI_POOL_DISCOVERY_V379",
        safe: true,
        readOnly: true,
        token,
        monitoredPair,
        status: "LIVE_STORAGE_READ_FAILED_V379",
        error: String(e?.message || e || "UNKNOWN_ERROR"),
        timestamp: now()
      }, 502);
    }

    // The V378 endpoint intentionally returns aggregates, not raw rows.
    // Pull a bounded set of exact known transaction hashes from retained buckets
    // using a new read-only DO endpoint below.
    let sample;
    try {
      const r = await stub.fetch(
        "https://v3-live.internal/recent-tx-sample-v379?maxTx=" + maxTx
      );
      sample = await r.json();
    } catch (e) {
      return jsonResponse({
        version: VERSION,
        diagnostic: "V3_CANDIDATE_MULTI_POOL_DISCOVERY_V379",
        safe: true,
        readOnly: true,
        token,
        monitoredPair,
        status: "RECENT_TX_SAMPLE_FAILED_V379",
        error: String(e?.message || e || "UNKNOWN_ERROR"),
        timestamp: now()
      }, 502);
    }

    const txHashes = Array.isArray(sample?.txHashes) ? sample.txHashes : [];
    const pools = new Map();
    const transactions = [];
    let receiptRequests = 0;
    let metadataRequests = 0;

    for (const txHash of txHashes) {
      receiptRequests++;
      const receiptCall = await v356RawAlchemyRpc(
        alchemyUrl,
        "eth_getTransactionReceipt",
        [txHash],
        6000
      );

      if (!receiptCall?.ok || !receiptCall?.result) {
        transactions.push({
          txHash,
          receiptFound: false,
          candidatePools: [],
          error: receiptCall?.error || "RECEIPT_UNAVAILABLE"
        });
        continue;
      }

      const logs = Array.isArray(receiptCall.result.logs) ? receiptCall.result.logs : [];
      const swapLogs = logs.filter(log =>
        String(log?.topics?.[0] || "").toLowerCase() === UNISWAP_V3_SWAP_TOPIC_V326
      );

      const candidatePools = [];
      const candidateSwapEvidenceV386 = [];

      for (const log of swapLogs) {
        const pool = normalize(log?.address || "");
        if (!isAddress(pool)) continue;

        let meta = pools.get(pool);
        if (!meta) {
          // Four bounded metadata calls, cached per unique pool during this diagnostic.
          const [t0r, t1r, feeR, factoryR] = await Promise.all([
            v375EthCallRaw(alchemyUrl, pool, UNISWAP_V3_TOKEN0_SELECTOR_V326),
            v375EthCallRaw(alchemyUrl, pool, UNISWAP_V3_TOKEN1_SELECTOR_V326),
            v375EthCallRaw(alchemyUrl, pool, UNISWAP_V3_FEE_SELECTOR_V328),
            v375EthCallRaw(alchemyUrl, pool, UNISWAP_V3_FACTORY_SELECTOR_V375)
          ]);
          metadataRequests += 4;

          const token0 = t0r?.ok ? decodeEthCallAddressV326(t0r.result) : null;
          const token1 = t1r?.ok ? decodeEthCallAddressV326(t1r.result) : null;
          const fee = feeR?.ok ? decodeUintWordV375(feeR.result) : null;
          const factory = factoryR?.ok ? decodeEthCallAddressV326(factoryR.result) : null;

          meta = {
            pool,
            token0,
            token1,
            fee,
            factory,
            factoryVerified: factory === UNISWAP_V3_FACTORY_V195,
            candidateInPool: token0 === token || token1 === token,
            quoteToken: token0 === token ? token1 : token1 === token ? token0 : null,
            isMonitoredPair: monitoredPair === pool,
            observedSwapLogs: 0,
            observedTransactions: new Set()
          };
          pools.set(pool, meta);
        }

        meta.observedSwapLogs++;
        meta.observedTransactions.add(txHash);

        if (meta.candidateInPool && meta.factoryVerified) {
          candidatePools.push(pool);
          candidateSwapEvidenceV386.push({
            pool,
            logIndex: log?.logIndex ?? null,
            blockNumber: log?.blockNumber ?? receiptCall.result?.blockNumber ?? null,
            topics: Array.isArray(log?.topics) ? log.topics.slice(0, 4) : [],
            data: String(log?.data || "0x")
          });
        }
      }

      transactions.push({
        txHash,
        receiptFound: true,
        blockNumber: rpcBlockNumberV331(receiptCall.result?.blockNumber),
        v3SwapLogs: swapLogs.length,
        candidatePools: [...new Set(candidatePools)],
        // V386: bounded evidence captured from the receipt already fetched above.
        // This is read-only and lets route aggregation reuse evidence without
        // issuing a duplicate eth_getTransactionReceipt request.
        candidateSwapEvidenceV386
      });
    }

    const discoveredPools = [...pools.values()]
      .filter(p => p.candidateInPool && p.factoryVerified)
      .map(p => ({
        pool: p.pool,
        token0: p.token0,
        token1: p.token1,
        fee: p.fee,
        factory: p.factory,
        factoryVerified: p.factoryVerified,
        quoteToken: p.quoteToken,
        quoteSymbol:
          p.quoteToken === CANONICAL_WETH_V179 ? "WETH" :
          p.quoteToken === CANONICAL_USDG_V179 ? "USDG" :
          null,
        isMonitoredPair: p.isMonitoredPair,
        observedSwapLogs: p.observedSwapLogs,
        observedTransactions: p.observedTransactions.size
      }))
      .sort((a, b) =>
        Number(b.isMonitoredPair) - Number(a.isMonitoredPair) ||
        b.observedSwapLogs - a.observedSwapLogs
      );

    // V387: verified multi-pool registry PREVIEW only.
    // No persistence yet: validate schema/evidence before introducing KV writes.
    const verifiedMultiPoolRegistryPreviewV387 = discoveredPools.map(p => ({
      pool: normalize(p.pool || ""),
      token0: normalize(p.token0 || ""),
      token1: normalize(p.token1 || ""),
      quoteToken: normalize(p.quoteToken || ""),
      quoteSymbol: p.quoteSymbol || "UNVERIFIED",
      fee: p.fee ?? null,
      factory: normalize(p.factory || ""),
      factoryVerified: p.factoryVerified === true,
      candidateToken: token,
      isMonitoredPair: !!p.isMonitoredPair,
      observedSwapLogs: Number(p.observedSwapLogs || 0),
      observedTransactions: Number(p.observedTransactions || 0),
      registryStatus: "VERIFIED_OBSERVED_POOL_V387"
    })).filter(p =>
      isAddress(p.pool) &&
      p.factoryVerified === true &&
      (p.token0 === token || p.token1 === token)
    );

    const additionalPools = discoveredPools.filter(p => !p.isMonitoredPair);

    // V388: merge; never replace the registry with only the latest bounded sample.
    // Admission is restricted to the V387 factory-verified candidate-pool preview.
    const persistentRegistryV388 = await v388MergeVerifiedPoolRegistry(
      env,
      token,
      verifiedMultiPoolRegistryPreviewV387
    );

    return jsonResponse({
      version: VERSION,
      diagnostic: "V3_CANDIDATE_MULTI_POOL_DISCOVERY_V379",
      safe: true,
      readOnly: true,
      workersKvWrites: persistentRegistryV388.writeSuccess ? 1 : 0,
      durableObjectTradeWrites: 0,
      scoringMutated: false,
      collectorMutated: false,
      token,
      monitoredPair,
      sampleSource: "RETAINED_LIVE_TRANSACTION_RECEIPTS_V379",
      sampleLimit: maxTx,
      sampledTransactions: txHashes.length,
      receiptRequests,
      metadataRequests,
      totalDiagnosticRpcRequests: receiptRequests + metadataRequests,
      discoveredVerifiedCandidatePools: discoveredPools.length,
      additionalVerifiedCandidatePools: additionalPools.length,
      verifiedMultiPoolRegistryPreviewV387,
      registryPreviewV387: {
        enabled: true,
        readOnly: true,
        persistent: false,
        schemaVersion: "V387",
        eligiblePools: verifiedMultiPoolRegistryPreviewV387.length,
        factoryVerifiedOnly: true,
        candidatePoolsOnly: true,
        workersKvWrites: 0,
        durableObjectWrites: 0,
        scoringMutated: false,
        collectorMutated: false,
        persistenceDeferredUntilValidated: true
      },
      persistentRegistryV388: {
        enabled: true,
        persistent: true,
        mergeNotReplace: true,
        schemaVersion: persistentRegistryV388.schemaVersion,
        diagnosticSemanticsVersion: "V392",
        binding: persistentRegistryV388.binding,
        previousEntries: persistentRegistryV388.previousEntries,
        observedEligiblePools: persistentRegistryV388.observedEligiblePools,
        newlyAdded: persistentRegistryV388.newlyAdded,
        refreshed: persistentRegistryV388.refreshed,
        registryEntries: persistentRegistryV388.entries.length,
        entries: (persistentRegistryV388.entries || []).map(entry => ({
          ...entry,
          evidenceSemanticsV392: {
            observedTransactionsTotalIsUniqueLifetime: false,
            observedSwapLogsTotalIsUniqueLifetime: false,
            verifiedUniqueLifetimeTransactions: null,
            verifiedUniqueLifetimeSwapLogs: null,
            activityUse: "DO_NOT_USE_FOR_SCORING_OR_LIVE_FLOW_TOTALS",
            registryUse: "VERIFIED_POOL_MEMBERSHIP_AND_METADATA_ONLY"
          }
        })),
        accountingV391: {
          lifetimeCountersAreUnique: false,
          counterMode: "NON_INFLATING_HIGH_WATER_UNTIL_UNIQUE_IDS_PERSISTED",
          volatileObservationFieldsExcludedFromWriteDecision: true
        },
        registrySemanticsV392: {
          observedTransactionsTotalMeaning: "LEGACY_NON_UNIQUE_HIGH_WATER_EVIDENCE_DO_NOT_USE_AS_LIFETIME_ACTIVITY",
          observedSwapLogsTotalMeaning: "LEGACY_NON_UNIQUE_HIGH_WATER_EVIDENCE_DO_NOT_USE_AS_LIFETIME_ACTIVITY",
          verifiedUniqueLifetimeTransactions: null,
          verifiedUniqueLifetimeSwapLogs: null,
          uniqueLifetimeEvidenceStatus: "UNVERIFIED_UNTIL_UNIQUE_TX_LOG_IDENTITIES_ARE_PERSISTED",
          safeForScoring: false,
          safeForLiveFlowTotals: false,
          safeForPoolMembership: true,
          safeForVerifiedPoolMetadata: true
        },
        meaningfulChangeV390: persistentRegistryV388.meaningfulChangeV390,
        writeAttempted: persistentRegistryV388.writeAttempted,
        writeSuccess: persistentRegistryV388.writeSuccess,
        writeSkippedReasonV390: persistentRegistryV388.writeSkippedReasonV390,
        writeError: persistentRegistryV388.writeError,
        scoringMutated: false,
        collectorMutated: false,
        liveSubscriptionMutated: false
      },
      pools: discoveredPools,
      transactions,
      coverageNote: "OBSERVED_ROUTE_DISCOVERY_ONLY_NOT_EXHAUSTIVE_FACTORY_ENUMERATION_V379",
      status: additionalPools.length > 0
        ? "ADDITIONAL_VERIFIED_V3_POOLS_DISCOVERED_V379"
        : discoveredPools.length > 0
          ? "ONLY_MONITORED_VERIFIED_V3_POOL_OBSERVED_V379"
          : "NO_VERIFIED_CANDIDATE_V3_POOL_OBSERVED_IN_SAMPLE_V379",
      interpretation: additionalPools.length > 0
        ? "One or more additional factory-verified Uniswap V3 pools containing the candidate token were observed in retained live transaction routes. This is discovery evidence only; no subscriptions or scoring were changed."
        : "No additional candidate V3 pool was observed in this bounded retained-transaction sample. This does not prove no other pools exist.",
      timestamp: now()
    });
  }

  if (path === "/v3aggregation-diagnostic") {
    const token = normalize(url.searchParams.get("token") || "");
    if (!isAddress(token)) {
      return jsonResponse({
        version: VERSION,
        diagnostic: "V3_ROLLING_USD_AGGREGATION_RECONCILIATION_V378",
        safe: true,
        readOnly: true,
        status: "INVALID_TOKEN_V378"
      }, 400);
    }

    if (!env?.V3_LIVE_COLLECTOR) {
      return jsonResponse({
        version: VERSION,
        diagnostic: "V3_ROLLING_USD_AGGREGATION_RECONCILIATION_V378",
        safe: true,
        readOnly: true,
        status: "V3_LIVE_COLLECTOR_BINDING_UNAVAILABLE_V378"
      }, 503);
    }

    const auditNow = Date.now();
    const id = env.V3_LIVE_COLLECTOR.idFromName(token);
    const stub = env.V3_LIVE_COLLECTOR.get(id);

    let rawAudit = null;
    let normalWindows = null;
    const errors = [];

    try {
      const r = await stub.fetch(
        "https://v3-live.internal/aggregation-audit-v378?now=" + auditNow
      );
      rawAudit = await r.json();
    } catch (e) {
      errors.push("RAW_AUDIT:" + String(e?.message || e || "UNKNOWN_ERROR"));
    }

    try {
      const r = await stub.fetch("https://v3-live.internal/windows");
      normalWindows = await r.json();
    } catch (e) {
      errors.push("NORMAL_WINDOWS:" + String(e?.message || e || "UNKNOWN_ERROR"));
    }

    const normalMap = normalWindows?.windows || {};
    const rawMap = rawAudit?.windows || {};
    const labels = ["5m", "15m", "1h", "6h", "24h"];
    const comparison = {};

    const pickNum = (obj, keys) => {
      for (const k of keys) {
        const n = Number(obj?.[k]);
        if (Number.isFinite(n)) return n;
      }
      return null;
    };

    for (const label of labels) {
      const raw = rawMap?.[label] || null;
      const normal = normalMap?.[label] || null;

      const normalBuys = pickNum(normal, ["buys", "buyCount", "buyTrades"]);
      const normalSells = pickNum(normal, ["sells", "sellCount", "sellTrades"]);
      const normalBuyUsd = pickNum(normal, ["buyUsd", "buyUSD", "buyUsdTotal"]);
      const normalSellUsd = pickNum(normal, ["sellUsd", "sellUSD", "sellUsdTotal"]);

      comparison[label] = {
        raw: raw ? {
          buys: raw.buys,
          sells: raw.sells,
          buyUsd: raw.buyUsd,
          sellUsd: raw.sellUsd,
          netUsd: raw.netUsd,
          buyPressurePct: raw.buyPressurePct,
          duplicateEventRows: raw.duplicateEventRows,
          usdValued: raw.usdValued,
          rawRows: raw.rawRows
        } : null,
        normal: normal || null,
        comparableFields: {
          buysMatch: raw && normalBuys !== null ? raw.buys === normalBuys : null,
          sellsMatch: raw && normalSells !== null ? raw.sells === normalSells : null,
          buyUsdDelta: raw && normalBuyUsd !== null
            ? Number((raw.buyUsd - normalBuyUsd).toFixed(12))
            : null,
          sellUsdDelta: raw && normalSellUsd !== null
            ? Number((raw.sellUsd - normalSellUsd).toFixed(12))
            : null
        }
      };
    }

    const comparable = Object.values(comparison).flatMap(x => [
      x?.comparableFields?.buysMatch,
      x?.comparableFields?.sellsMatch,
      x?.comparableFields?.buyUsdDelta === null ? null : Math.abs(x.comparableFields.buyUsdDelta) < 0.000001,
      x?.comparableFields?.sellUsdDelta === null ? null : Math.abs(x.comparableFields.sellUsdDelta) < 0.000001
    ]).filter(v => v !== null);

    const allMatch = comparable.length > 0 && comparable.every(Boolean);

    return jsonResponse({
      version: VERSION,
      diagnostic: "V3_ROLLING_USD_AGGREGATION_RECONCILIATION_V378",
      safe: true,
      readOnly: true,
      workersKvWrites: 0,
      durableObjectTradeWrites: 0,
      scoringMutated: false,
      token,
      auditNow,
      rawAudit,
      normalWindows,
      comparison,
      comparableChecks: comparable.length,
      allComparableChecksMatch: allMatch,
      errors,
      status: errors.length
        ? "AGGREGATION_DIAGNOSTIC_PARTIAL_V378"
        : allMatch
          ? "RAW_AND_ROLLING_AGGREGATION_MATCH_V378"
          : "RAW_AND_ROLLING_AGGREGATION_DIFFER_V378",
      interpretation: errors.length
        ? "One or more read-only audit paths failed; do not infer an aggregation mismatch from incomplete evidence."
        : allMatch
          ? "Independent recomputation from retained raw trade buckets matches the collector's normal rolling-window aggregation for all comparable fields."
          : "At least one comparable rolling-window field differs from an independent recomputation of retained raw trade buckets. Inspect per-window deltas before changing collector logic.",
      timestamp: now()
    });
  }


  if (path === "/v3route-aggregation-diagnostic") {
    const token = normalize(url.searchParams.get("token") || "");
    const maxTxRaw = Number(url.searchParams.get("maxTx"));
    const maxTx = Number.isFinite(maxTxRaw)
      ? Math.max(1, Math.min(20, Math.trunc(maxTxRaw)))
      : 12;

    if (!isAddress(token)) {
      return jsonResponse({
        version: VERSION,
        diagnostic: "V3_MULTI_POOL_ROUTE_AWARE_AGGREGATION_V381",
        safe: true,
        readOnly: true,
        status: "INVALID_TOKEN_V381"
      }, 400);
    }

    if (!env?.V3_LIVE_COLLECTOR) {
      return jsonResponse({
        version: VERSION,
        diagnostic: "V3_MULTI_POOL_ROUTE_AWARE_AGGREGATION_V381",
        safe: true,
        readOnly: true,
        status: "V3_LIVE_COLLECTOR_BINDING_UNAVAILABLE_V381"
      }, 503);
    }

    // Reuse the already-proven V379 discovery path first.
    const discoveryUrl = new URL(url.toString());
    discoveryUrl.pathname = "/v3multipool-diagnostic";
    discoveryUrl.searchParams.set("token", token);
    discoveryUrl.searchParams.set("maxTx", String(maxTx));

    let discovery;
    try {
      const req = new Request(discoveryUrl.toString(), {
        method: "GET",
        headers: request.headers
      });
      const resp = await handleRequest(req, env);
      discovery = await resp.json();
    } catch (e) {
      return jsonResponse({
        version: VERSION,
        diagnostic: "V3_MULTI_POOL_ROUTE_AWARE_AGGREGATION_V381",
        safe: true,
        readOnly: true,
        token,
        error: String(e?.message || e || "DISCOVERY_FAILED"),
        status: "MULTI_POOL_DISCOVERY_FAILED_V381"
      }, 500);
    }

    const verifiedPools = Array.isArray(discovery?.pools)
      ? discovery.pools.filter(p => p?.factoryVerified === true && isAddress(p?.pool))
      : [];

    const poolByAddress = new Map(
      verifiedPools.map(p => [normalize(p.pool), p])
    );

    const txs = Array.isArray(discovery?.transactions)
      ? discovery.transactions.filter(t =>
          t?.receiptFound === true &&
          /^0x[0-9a-fA-F]{64}$/.test(String(t?.txHash || ""))
        )
      : [];

    const poolStats = {};
    for (const p of verifiedPools) {
      const key = normalize(p.pool);
      poolStats[key] = {
        pool: key,
        token0: normalize(p.token0 || ""),
        token1: normalize(p.token1 || ""),
        quoteToken: normalize(p.quoteToken || ""),
        quoteSymbol: p.quoteSymbol || "UNVERIFIED",
        fee: p.fee ?? null,
        isMonitoredPair: !!p.isMonitoredPair,
        transactionsTouched: 0,
        candidateSwapLogs: 0,
        buys: 0,
        sells: 0,
        unknownDirection: 0,
        candidateInRaw: 0,
        candidateOutRaw: 0,
        quoteInRaw: 0,
        quoteOutRaw: 0
      };
    }

    const transactionResults = [];
    let receiptRequests = 0; // V386 deliberately makes zero second-pass receipt requests.
    let reusedReceiptEvidence = 0;
    let totalCandidateSwapLogs = 0;
    let routeMultiPoolTransactions = 0;
    let routeSinglePoolTransactions = 0;
    let routeUnknownTransactions = 0;

    const decodeSigned256V386 = (word) => {
      let x = BigInt("0x" + word);
      if (x >= (1n << 255n)) x -= (1n << 256n);
      return x;
    };

    for (const tx of txs) {
      const evidence = Array.isArray(tx?.candidateSwapEvidenceV386)
        ? tx.candidateSwapEvidenceV386
        : [];

      if (evidence.length === 0) {
        transactionResults.push({
          txHash: tx.txHash,
          blockNumber: tx?.blockNumber ?? null,
          receiptFound: true,
          evidenceReusedV386: false,
          candidatePoolsTouched: [],
          candidatePoolCount: 0,
          routeClass: "NO_REUSABLE_CANDIDATE_SWAP_EVIDENCE_V386",
          candidateSwapLogs: 0,
          decodedSwaps: []
        });
        routeUnknownTransactions++;
        continue;
      }

      reusedReceiptEvidence++;
      const perTxPools = new Set();
      const decodedSwaps = [];

      for (const log of evidence) {
        const topic0 = normalize(log?.topics?.[0] || "");
        const emitter = normalize(log?.pool || "");
        if (
          topic0 !== normalize(UNISWAP_V3_SWAP_TOPIC_V326) ||
          !poolByAddress.has(emitter)
        ) continue;

        const meta = poolByAddress.get(emitter);
        const token0 = normalize(meta?.token0 || "");
        const token1 = normalize(meta?.token1 || "");
        const candidateIs0 = token0 === token;
        const candidateIs1 = token1 === token;
        if (!candidateIs0 && !candidateIs1) continue;

        const dataHex = String(log?.data || "");
        if (!/^0x[0-9a-fA-F]{128,}$/.test(dataHex)) continue;
        const words = dataHex.slice(2).match(/.{64}/g) || [];
        if (words.length < 2) continue;

        let amount0, amount1;
        try {
          amount0 = decodeSigned256V386(words[0]);
          amount1 = decodeSigned256V386(words[1]);
        } catch {
          continue;
        }

        const candidateDelta = candidateIs0 ? amount0 : amount1;
        const quoteDelta = candidateIs0 ? amount1 : amount0;
        const side = candidateDelta < 0n
          ? "BUY"
          : candidateDelta > 0n
            ? "SELL"
            : "UNKNOWN";

        perTxPools.add(emitter);
        totalCandidateSwapLogs++;

        const ps = poolStats[emitter];
        if (ps) {
          ps.candidateSwapLogs++;
          if (side === "BUY") ps.buys++;
          else if (side === "SELL") ps.sells++;
          else ps.unknownDirection++;

          if (candidateDelta > 0n) ps.candidateInRaw += Number(candidateDelta > BigInt(Number.MAX_SAFE_INTEGER) ? 0n : candidateDelta);
          if (candidateDelta < 0n) {
            const v = -candidateDelta;
            ps.candidateOutRaw += Number(v > BigInt(Number.MAX_SAFE_INTEGER) ? 0n : v);
          }
          if (quoteDelta > 0n) ps.quoteInRaw += Number(quoteDelta > BigInt(Number.MAX_SAFE_INTEGER) ? 0n : quoteDelta);
          if (quoteDelta < 0n) {
            const v = -quoteDelta;
            ps.quoteOutRaw += Number(v > BigInt(Number.MAX_SAFE_INTEGER) ? 0n : v);
          }
        }

        decodedSwaps.push({
          pool: emitter,
          logIndex: log?.logIndex ?? null,
          side,
          candidateTokenIs: candidateIs0 ? "token0" : "token1",
          amount0Raw: amount0.toString(),
          amount1Raw: amount1.toString(),
          candidateDeltaRaw: candidateDelta.toString(),
          quoteDeltaRaw: quoteDelta.toString(),
          quoteSymbol: meta?.quoteSymbol || "UNVERIFIED"
        });
      }

      for (const pool of perTxPools) {
        if (poolStats[pool]) poolStats[pool].transactionsTouched++;
      }

      let routeClass = "NO_VERIFIED_CANDIDATE_POOL_SWAP_V386";
      if (perTxPools.size === 1) {
        routeClass = "SINGLE_VERIFIED_CANDIDATE_POOL_V386";
        routeSinglePoolTransactions++;
      } else if (perTxPools.size > 1) {
        routeClass = "MULTI_VERIFIED_CANDIDATE_POOL_ROUTE_V386";
        routeMultiPoolTransactions++;
      } else {
        routeUnknownTransactions++;
      }

      transactionResults.push({
        txHash: tx.txHash,
        blockNumber: tx?.blockNumber ?? null,
        receiptFound: true,
        evidenceReusedV386: true,
        candidatePoolsTouched: Array.from(perTxPools),
        candidatePoolCount: perTxPools.size,
        routeClass,
        candidateSwapLogs: decodedSwaps.length,
        decodedSwaps
      });
    }

    const pools = Object.values(poolStats);
    const aggregateBuys = pools.reduce((a, p) => a + p.buys, 0);
    const aggregateSells = pools.reduce((a, p) => a + p.sells, 0);

    // Route-aware token-level count: one touched transaction = one routed token-flow event,
    // regardless of how many candidate pools were traversed in that transaction.
    const tokenLevelTransactions = transactionResults.filter(
      x => x.receiptFound && x.candidatePoolCount > 0
    ).length;

    return jsonResponse({
      version: VERSION,
      diagnostic: "V3_MULTI_POOL_ROUTE_AWARE_AGGREGATION_V381",
      safe: true,
      readOnly: true,
      workersKvWrites: 0,
      durableObjectTradeWrites: 0,
      scoringMutated: false,
      collectorMutated: false,
      token,
      discoverySource: "V379_FACTORY_VERIFIED_OBSERVED_ROUTE_DISCOVERY",
      sampleLimit: maxTx,
      sampledTransactions: txs.length,
      receiptRequests,
      duplicateReceiptRequestsAvoidedV386: txs.length,
      reusedReceiptEvidenceV386: reusedReceiptEvidence,
      discoveryReceiptRequests: Number(discovery?.receiptRequests || 0),
      discoveryMetadataRequests: Number(discovery?.metadataRequests || 0),
      verifiedCandidatePools: pools.length,
      routeSummary: {
        tokenLevelTransactions,
        singlePoolTransactions: routeSinglePoolTransactions,
        multiPoolTransactions: routeMultiPoolTransactions,
        noVerifiedCandidatePoolTransactions: routeUnknownTransactions,
        totalCandidateSwapLogs,
        poolLevelBuySwapLogs: aggregateBuys,
        poolLevelSellSwapLogs: aggregateSells,
        warning: "POOL_LEVEL_SWAP_COUNTS_ARE_NOT_TOKEN_LEVEL_TRANSACTION_COUNTS_V381"
      },
      pools,
      transactions: transactionResults,
      receiptEvidence: {
        requestedSecondPassV386: receiptRequests,
        discoveryReceiptsRequested: Number(discovery?.receiptRequests || 0),
        reusableReceiptTransactions: reusedReceiptEvidence,
        usableReceipts: transactionResults.filter(x => x.receiptFound === true).length,
        failedReceipts: transactionResults.filter(x => x.receiptFound !== true).length,
        candidateSwapLogsDecoded: totalCandidateSwapLogs,
        multiPoolRoutesDecoded: routeMultiPoolTransactions,
        duplicateReceiptFetchesEliminatedV386: true
      },
      coverageNote: "OBSERVED_RETAINED_ROUTE_SAMPLE_ONLY_NOT_EXHAUSTIVE_POOL_ENUMERATION_V386",
      status:
        transactionResults.filter(x => x.receiptFound === true).length === 0
          ? "RECEIPT_EVIDENCE_UNAVAILABLE_V384"
          : totalCandidateSwapLogs === 0
            ? "RECEIPTS_AVAILABLE_BUT_NO_CANDIDATE_SWAPS_DECODED_V384"
            : pools.length > 1 && routeMultiPoolTransactions > 0
              ? "MULTI_POOL_ROUTE_AWARE_AGGREGATION_PROVEN_V386"
              : pools.length > 1
                ? "MULTIPLE_VERIFIED_POOLS_KNOWN_ROUTE_AGGREGATION_SAMPLE_SINGLE_POOL_ONLY_V386"
                : pools.length === 1
                  ? "SINGLE_VERIFIED_POOL_ROUTE_AGGREGATION_PROVEN_V386"
                  : "NO_VERIFIED_CANDIDATE_POOLS_OBSERVED_V384",
      interpretation:
        transactionResults.filter(x => x.receiptFound === true).length === 0
          ? "DATA UNVERIFIED: no usable transaction receipts were returned, so route-aware aggregation is not proven in this run."
          : totalCandidateSwapLogs === 0
            ? "DATA UNVERIFIED: receipts were returned but no verified candidate-pool swaps were decoded."
            : pools.length > 1 && routeMultiPoolTransactions > 0
              ? "Route-aware aggregation is proven in this sample: multiple factory-verified candidate pools were decoded in at least one transaction, while token-level transaction counts remain deduplicated from pool-level swap counts."
              : "Receipt and swap evidence was decoded, but this sample did not contain a decoded multi-pool candidate route. No collector or scoring changes were made.",
      timestamp: now()
    });
  }

  if (path === "/v3live-tx-lookup") {
    const token = normalize(url.searchParams.get("token") || "");
    const txHash = String(url.searchParams.get("tx") || "").toLowerCase();

    if (!isAddress(token)) {
      return jsonResponse({
        version: VERSION,
        diagnostic: "V3_LIVE_EXACT_TX_STORAGE_RECONCILIATION_V376",
        safe: true,
        readOnly: true,
        status: "INVALID_TOKEN_V376"
      }, 400);
    }

    if (!/^0x[a-f0-9]{64}$/.test(txHash)) {
      return jsonResponse({
        version: VERSION,
        diagnostic: "V3_LIVE_EXACT_TX_STORAGE_RECONCILIATION_V376",
        safe: true,
        readOnly: true,
        status: "INVALID_TX_HASH_V376"
      }, 400);
    }

    if (!env?.V3_LIVE_COLLECTOR) {
      return jsonResponse({
        version: VERSION,
        diagnostic: "V3_LIVE_EXACT_TX_STORAGE_RECONCILIATION_V376",
        safe: true,
        readOnly: true,
        status: "V3_LIVE_COLLECTOR_BINDING_UNAVAILABLE_V376"
      }, 503);
    }

    const id = env.V3_LIVE_COLLECTOR.idFromName(token);
    const stub = env.V3_LIVE_COLLECTOR.get(id);
    const internalUrl =
      "https://v3-live.internal/tx-lookup-v376?tx=" + encodeURIComponent(txHash);

    let storageResult = null;
    try {
      const response = await stub.fetch(internalUrl);
      storageResult = await response.json();
    } catch (e) {
      return jsonResponse({
        version: VERSION,
        diagnostic: "V3_LIVE_EXACT_TX_STORAGE_RECONCILIATION_V376",
        safe: true,
        readOnly: true,
        workersKvWrites: 0,
        durableObjectTradeWrites: 0,
        scoringMutated: false,
        token,
        txHash,
        status: "LIVE_STORAGE_LOOKUP_FAILED_V376",
        error: String(e?.message || e || "UNKNOWN_ERROR"),
        timestamp: now()
      }, 502);
    }

    return jsonResponse({
      version: VERSION,
      diagnostic: "V3_LIVE_EXACT_TX_STORAGE_RECONCILIATION_V376",
      safe: true,
      readOnly: true,
      workersKvWrites: 0,
      durableObjectTradeWrites: 0,
      scoringMutated: false,
      token,
      txHash,
      storage: storageResult,
      found: storageResult?.found === true,
      matchesFound: Number(storageResult?.matchesFound || 0),
      matches: Array.isArray(storageResult?.matches) ? storageResult.matches : [],
      status: storageResult?.found === true
        ? "EXACT_TX_FOUND_IN_LIVE_COLLECTOR_V376"
        : "EXACT_TX_NOT_FOUND_IN_LIVE_COLLECTOR_V376",
      interpretation: storageResult?.found === true
        ? "The exact transaction is present in retained Durable Object live storage."
        : "The exact transaction is absent from retained Durable Object live storage. Check whether its block/time falls inside healthy continuous collector coverage before classifying this as a missed live event.",
      timestamp: now()
    });
  }

  if (path === "/v3tx-diagnostic") {
    return jsonResponse(
      await v3ExactTxDiagnosticV375(
        env,
        url.searchParams.get("token") || "",
        url.searchParams.get("tx") || ""
      )
    );
  }


  if (path === "/v3reconcile-diagnostic") {
    return jsonResponse(
      await v3ReconcileDiagnosticV374(
        env,
        url.searchParams.get("token") || "",
        url.searchParams.get("blocks") || "40"
      )
    );
  }


  if (path === "/v3multipool-plan") {
    return jsonResponse(
      await v393MultiPoolSubscriptionPlan(
        env,
        url.searchParams.get("token") || ""
      )
    );
  }

  if (path === "/v3multipool-shadow-start") {
    return jsonResponse(await v3LiveCollectorRouteV363(env, url.searchParams.get("token") || "", "shadowstart"));
  }
  if (path === "/v3multipool-shadow-status") {
    return jsonResponse(await v3LiveCollectorRouteV363(env, url.searchParams.get("token") || "", "shadowstatus"));
  }

  if (path === "/v3live-start") {
    return jsonResponse(await v3LiveCollectorRouteV363(env, url.searchParams.get("token") || "", "start"));
  }
  if (path === "/v3live-status") {
    return jsonResponse(await v3LiveCollectorRouteV363(env, url.searchParams.get("token") || "", "status"));
  }
  if (path === "/v3live-windows") {
    return jsonResponse(await v3LiveCollectorRouteV363(env, url.searchParams.get("token") || "", "windows"));
  }
  if (path === "/v3live-stop") {
    return jsonResponse(await v3LiveCollectorRouteV363(env, url.searchParams.get("token") || "", "stop"));
  }

  if (
    path ===
    "/rpc-test"
  ) {
    return jsonResponse(
      await rpcTest(
        env
      )
    );
  }

  if (
    path ===
    "/scan"
  ) {
    return jsonResponse(
      await scan(
        env,
        {
          scheduled:
            false
        }
      )
    );
  }

  if (
    path ===
    "/state"
  ) {
    return jsonResponse(
      await stateStatus(
        env
      )
    );
  }

  if (
    path ===
    "/diagnostics"
  ) {
    return jsonResponse(
      await diagnostics(
        env
      )
    );
  }

  if (
    path ===
    "/run-all"
  ) {
    return jsonResponse(
      await runAll(
        env
      )
    );
  }

  if (
    path ===
    "/test-telegram"
  ) {
    return jsonResponse(
      await telegramTest(
        env
      )
    );
  }

  if (
    path ===
    "/telegram-webhook-setup"
  ) {
    return jsonResponse(
      await telegramWebhookSetupV271(
        request,
        env
      )
    );
  }

  if (
    path ===
    "/telegram-webhook-status"
  ) {
    return jsonResponse(
      await telegramWebhookStatusV273(
        env
      )
    );
  }

  if (
    path ===
    "/telegram-webhook-info"
  ) {
    return jsonResponse(
      await telegramWebhookInfoV274(
        env
      )
    );
  }

  if (
    path ===
    "/last-alert-scan"
  ) {
    return jsonResponse(
      await lastAlertScanV264(
        env
      )
    );
  }

  if (
    path ===
    "/alert-history"
  ) {
    return jsonResponse(
      await alertHistoryV268(
        env
      )
    );
  }

  if (
    path ===
    "/call-performance"
  ) {
    const loaded =
      await readState(
        env
      );

    return jsonResponse(
      callPerformanceReportV270(
        loaded?.state ||
        newState()
      )
    );
  }

  return jsonResponse(
    {
      agent:
        "Robinhood Chain Meme Hunter",

      version:
        VERSION,

      success:
        false,

      error:
        "NOT_FOUND",

      routes: [
        "/health",
        "/rpc-test",
        "/scan",
        "/state",
        "/diagnostics",
        "/run-all",
        "/test-telegram",
        "/telegram-webhook",
        "/telegram-webhook-setup",
        "/telegram-webhook-status",
        "/telegram-webhook-info",
        "/last-alert-scan",
        "/alert-history",
        "/call-performance"
      ],

      timestamp:
        now()
    },

    404
  );
}


/* ============================================================
   V333 STEP 1A — AUTONOMOUS NATIVE V3 COLLECTOR
   ============================================================
   Forward-only extension of the V331 ledger.
   - Runs after the normal scheduled scan with its OWN small request budget.
   - Reads only V329 on-chain-verified V3 pair identities registered in KV.
   - Captures exact Swap logs from the next bounded 10-block range.
   - Persists exact tx/log evidence through the existing V331 ledger writer.
   - Never claims complete coverage when the collector is behind.
   - Does not alter scanner scoring, qualification, alert thresholds or the
     scanner's existing request budget.
*/
const NATIVE_V3_COLLECTOR_REGISTRY_KEY_V333 = "robinhood-meme-hunter-v333-v3-collector-registry";
const NATIVE_V3_COLLECTOR_MAX_TOKENS_PER_RUN_V333 = 4;
const NATIVE_V3_COLLECTOR_BLOCKS_PER_RUN_V333 = 10;
const NATIVE_V3_COLLECTOR_REQUEST_LIMIT_V333 = 8;
const NATIVE_V3_TIMESTAMP_HYDRATE_MAX_PER_RUN_V334 = 3;

async function registerNativeV3CollectorTokenV333(env, tokenAddress, decimals = null) {
  const token = normalize(tokenAddress);
  const {kv} = getKV(env);
  if (!kv || !isAddress(token)) return {saved:false,status:"COLLECTOR_REGISTRY_UNAVAILABLE_V333"};
  try {
    let rows=[];
    const raw=await kv.get(NATIVE_V3_COLLECTOR_REGISTRY_KEY_V333);
    if(raw){ try{ const parsed=JSON.parse(raw); if(Array.isArray(parsed)) rows=parsed; }catch(_){} }
    const nowMs=Date.now();
    const d=Number(decimals);
    const existing=rows.find(r=>normalize(r?.tokenAddress)===token);
    if(existing){ existing.lastRegisteredAt=nowMs; if(Number.isInteger(d)&&d>=0&&d<=36) existing.decimals=d; }
    else rows.push({tokenAddress:token,decimals:Number.isInteger(d)&&d>=0&&d<=36?d:null,firstRegisteredAt:nowMs,lastRegisteredAt:nowMs});
    rows=rows.filter(r=>isAddress(normalize(r?.tokenAddress))).slice(-100);
    await kv.put(NATIVE_V3_COLLECTOR_REGISTRY_KEY_V333,JSON.stringify(rows));
    return {saved:true,status:"COLLECTOR_TOKEN_REGISTERED_V333",count:rows.length};
  }catch(error){return {saved:false,status:"COLLECTOR_REGISTRY_WRITE_ERROR_V333",error:String(error?.message||error).slice(0,160)};}
}

async function loadNativeV3CollectorRegistryV333(env) {
  const {kv} = getKV(env);
  if(!kv) return [];
  try{ const raw=await kv.get(NATIVE_V3_COLLECTOR_REGISTRY_KEY_V333); const rows=raw?JSON.parse(raw):[]; return Array.isArray(rows)?rows:[]; }catch(_){return [];}
}

function createNativeV3CollectorBudgetV333(){
  const b=createBudget();
  b.totalUsed=0; b.totalLimit=NATIVE_V3_COLLECTOR_REQUEST_LIMIT_V333;
  b.system.used=0; b.system.limit=0;
  b.discovery.used=0; b.discovery.limit=0; b.discovery.liveUsed=0; b.discovery.liveLimit=0; b.discovery.backlogUsed=0; b.discovery.backlogLimit=0;
  b.analysis.used=0; b.analysis.limit=NATIVE_V3_COLLECTOR_REQUEST_LIMIT_V333;
  b.notification.used=0; b.notification.limit=0; b.notification.globalReserveActiveV174=false;
  return b;
}

function nativeV3VerifiedTimestampMsV334(row){
  const ms=Number(row?.blockTimestampMs);
  return row?.timestampVerifiedV334===true && Number.isFinite(ms) && ms>0 ? ms : null;
}

async function hydrateNativeV3TradeTimestampsV334(env,budget,rows,maxLookups=NATIVE_V3_TIMESTAMP_HYDRATE_MAX_PER_RUN_V334){
  const input=Array.isArray(rows)?rows:[];
  const byBlock=new Map();
  for(const row of input){
    if(nativeV3VerifiedTimestampMsV334(row)) continue;
    const block=rpcBlockNumberV331(row?.blockNumber);
    if(!Number.isFinite(block)||byBlock.has(block)) continue;
    byBlock.set(block,[]);
  }
  for(const row of input){
    const block=rpcBlockNumberV331(row?.blockNumber);
    if(Number.isFinite(block)&&byBlock.has(block)) byBlock.get(block).push(row);
  }
  let lookups=0,verified=0;
  for(const [block,blockRows] of byBlock){
    if(lookups>=maxLookups||!budgetAvailable(budget,"analysis")) break;
    const result=await rpc(env,"eth_getBlockByNumber",["0x"+block.toString(16),false],budget,"analysis");
    lookups++;
    let timestampMs=null;
    try{
      const raw=String(result?.result?.timestamp||"");
      if(/^0x[a-fA-F0-9]+$/.test(raw)) timestampMs=Number(BigInt(raw))*1000;
    }catch(_){}
    if(!Number.isFinite(timestampMs)||timestampMs<=0) continue;
    for(const row of blockRows){
      row.blockTimestampMs=timestampMs;
      row.timestampVerifiedV334=true;
      row.timestampBasis="ONCHAIN_BLOCK_TIMESTAMP_V334";
      verified++;
    }
  }
  return {rows:input,lookups,verified};
}

function nativeV3RollingWindowsV334(records,nowMs=Date.now()){
  const allRows=Array.isArray(records)?records:[];
  const rows=allRows.filter(r=>nativeV3VerifiedTimestampMsV334(r));
  const defs=[["5m",5*60*1000],["15m",15*60*1000],["1h",60*60*1000],["6h",6*60*60*1000],["24h",24*60*60*1000]];
  const windows={};
  for(const [label,ms] of defs){
    let buys=0,sells=0;
    for(const row of rows){
      const ts=nativeV3VerifiedTimestampMsV334(row);
      if(!ts||ts<nowMs-ms||ts>nowMs) continue;
      if(row?.side==="BUY") buys++; else if(row?.side==="SELL") sells++;
    }
    windows[label]={buys,sells,swaps:buys+sells};
  }

  /* V337 Step 3A verification: zero-request audit of the exact quote-side
     amount fields introduced in V336. This is evidence readiness only; it
     intentionally does NOT promote WETH or USDG amounts to historical USD. */
  let quoteReadyRecordsV337=0,wethQuoteRecordsV337=0,usdgQuoteRecordsV337=0;
  let quoteReadyBuysV337=0,quoteReadySellsV337=0;
  for(const row of allRows){
    const quote=normalize(row?.quoteTokenAddress);
    const amount=Number(row?.quoteAmount);
    const ready=row?.quoteAmountVerifiedV336===true && Number.isFinite(amount) && amount>0 &&
      (quote===CANONICAL_WETH_V179 || quote===CANONICAL_USDG_V179);
    if(!ready) continue;
    quoteReadyRecordsV337++;
    if(quote===CANONICAL_WETH_V179) wethQuoteRecordsV337++;
    if(quote===CANONICAL_USDG_V179) usdgQuoteRecordsV337++;
    if(row?.side==="BUY") quoteReadyBuysV337++;
    else if(row?.side==="SELL") quoteReadySellsV337++;
  }

  return {
    verifiedTimestampRecords:rows.length,
    totalRecords:allRows.length,
    windows,
    coverage:"PARTIAL",
    quoteReadyRecordsV337,
    wethQuoteRecordsV337,
    usdgQuoteRecordsV337,
    quoteReadyBuysV337,
    quoteReadySellsV337
  };
}

async function collectOneNativeV3TokenV333(env,budget,row,headBlock){
  const token=normalize(row?.tokenAddress);
  const pairCache=await loadVerifiedV3PairIdentityV329(env,token);
  if(!pairCache?.valid) return {token,status:pairCache?.status||"PAIR_CACHE_UNAVAILABLE_V333",requestsUsed:0};
  const pair=normalize(pairCache.record?.pairAddress), token0=normalize(pairCache.record?.token0), token1=normalize(pairCache.record?.token1);
  let decimals=Number(row?.decimals);
  if(!Number.isInteger(decimals)||decimals<0||decimals>36) return {token,pair,status:"TOKEN_DECIMALS_UNVERIFIED_V333",requestsUsed:0};
  const ledger=await loadNativeV3SwapLedgerV331(env,token,pair);
  const priorLast=Number.isFinite(Number(ledger?.lastObservedBlock))?Number(ledger.lastObservedBlock):null;
  const toBlock=Math.trunc(headBlock);
  let fromBlock;
  let coverageGap=false;
  if(Number.isFinite(priorLast)&&priorLast<toBlock){
    fromBlock=priorLast+1;
    if(toBlock-fromBlock+1>NATIVE_V3_COLLECTOR_BLOCKS_PER_RUN_V333) coverageGap=true;
  }else if(Number.isFinite(priorLast)&&priorLast>=toBlock){
    return {token,pair,status:"COLLECTOR_CAUGHT_UP_V333",fromBlock:null,toBlock,swaps:0,coverageGap:false,requestsUsed:0};
  }else{
    fromBlock=Math.max(0,toBlock-NATIVE_V3_COLLECTOR_BLOCKS_PER_RUN_V333+1);
    coverageGap=true;
  }
  const rangeTo=Math.min(toBlock,fromBlock+NATIVE_V3_COLLECTOR_BLOCKS_PER_RUN_V333-1);
  if(!budgetAvailable(budget,"analysis")) return {token,pair,status:"COLLECTOR_BUDGET_EXHAUSTED_V333",requestsUsed:0};
  const before=safeNumber(budget.totalUsed);
  const logsResult=await rpc(env,"eth_getLogs",[{fromBlock:"0x"+fromBlock.toString(16),toBlock:"0x"+rangeTo.toString(16),address:pair,topics:[UNISWAP_V3_SWAP_TOPIC_V326]}],budget,"analysis");
  if(!Array.isArray(logsResult?.result)) return {token,pair,status:"COLLECTOR_LOGS_UNVERIFIED_V333",fromBlock,toBlock:rangeTo,coverageGap,requestsUsed:Math.max(0,safeNumber(budget.totalUsed)-before),error:logsResult?.error||null};
  const unique=new Map();
  for(const log of logsResult.result){
    const data=String(log?.data||"").replace(/^0x/i,""); if(data.length<128)continue;
    const amount0=signedInt256V326(data.slice(0,64)),amount1=signedInt256V326(data.slice(64,128)); if(typeof amount0!=="bigint"||typeof amount1!=="bigint")continue;
    const raw=token===token0?amount0:(token===token1?amount1:null); if(typeof raw!=="bigint"||raw===0n)continue;
    const amount=decimalFromSignedRawV326(raw,decimals); if(!Number.isFinite(amount)||amount===0)continue;
    const txHash=String(log?.transactionHash||"").toLowerCase(),logIndex=String(log?.logIndex??""); const tradeKey=`${txHash}|${logIndex}`; if(!txHash||unique.has(tradeKey))continue;
    const quoteTokenAddress=token===token0?token1:token0;
    const quoteRaw=token===token0?amount1:amount0;
    const quoteDecimals=quoteTokenAddress===CANONICAL_WETH_V179?18:(quoteTokenAddress===CANONICAL_USDG_V179?CANONICAL_USDG_DECIMALS_V179:null);
    const quoteAmount=Number.isInteger(quoteDecimals)?decimalFromSignedRawV326(quoteRaw,quoteDecimals):null;
    unique.set(tradeKey,{tradeKey,transactionHash:txHash,logIndex,blockNumber:rpcBlockNumberV331(log?.blockNumber),pairAddress:pair,side:raw<0n?"BUY":"SELL",tokenAmount:Math.abs(amount),quoteTokenAddress:isAddress(quoteTokenAddress)?quoteTokenAddress:null,quoteAmount:Number.isFinite(quoteAmount)&&quoteAmount!==0?Math.abs(quoteAmount):null,quoteAmountVerifiedV336:Number.isFinite(quoteAmount)&&quoteAmount!==0,quoteAmountBasisV336:Number.isFinite(quoteAmount)&&quoteAmount!==0?"EXACT_V3_SWAP_QUOTE_DELTA_V336":null,usd:null,usdVerified:false,priceUsd:null,observedAt:Date.now(),blockTimestampMs:null,timestampVerifiedV334:false,timestampBasis:"INGESTION_TIME_ONLY_V333"});
  }
  const scannedRange={fromBlock,toBlock:rangeTo,observedAt:Date.now(),swaps:logsResult.result.length,source:"SCHEDULED_NATIVE_V3_COLLECTOR_V333"};
  /* V334 Step 2A: hydrate exact on-chain block timestamps. New swaps are
     prioritised, then older ledger rows are progressively upgraded. */
  const existingMissing=(Array.isArray(ledger?.records)?ledger.records:[]).filter(r=>!nativeV3VerifiedTimestampMsV334(r));
  const hydrateInput=[...unique.values(),...existingMissing];
  const hydrated=await hydrateNativeV3TradeTimestampsV334(env,budget,hydrateInput,NATIVE_V3_TIMESTAMP_HYDRATE_MAX_PER_RUN_V334);
  const write=await persistNativeV3SwapLedgerV331(env,token,pair,hydrated.rows,[scannedRange]);
  return {token,pair,status:unique.size?"COLLECTOR_SWAPS_PERSISTED_V333":"COLLECTOR_ZERO_SWAPS_RANGE_PERSISTED_V333",fromBlock,toBlock:rangeTo,swaps:unique.size,coverageGap,ledgerWriteStatus:write?.status||null,timestampLookupsV334:hydrated.lookups,timestampsVerifiedV334:hydrated.verified,requestsUsed:Math.max(0,safeNumber(budget.totalUsed)-before)};
}

async function scheduledNativeV3CollectorV333(env){
  const budget=createNativeV3CollectorBudgetV333();
  const registry=await loadNativeV3CollectorRegistryV333(env);
  const selected=registry.slice(-NATIVE_V3_COLLECTOR_MAX_TOKENS_PER_RUN_V333);
  if(!selected.length) return {status:"NO_REGISTERED_V3_TOKENS_V333",tokens:0,requestsUsed:0,results:[]};
  const head=await rpc(env,"eth_blockNumber",[],budget,"analysis");
  let headBlock=null; try{if(head?.result)headBlock=Number(BigInt(head.result));}catch(_){}
  if(!Number.isFinite(headBlock)) return {status:"COLLECTOR_HEAD_UNVERIFIED_V333",tokens:selected.length,requestsUsed:safeNumber(budget.totalUsed),results:[]};
  const results=[];
  for(const row of selected){ if(!budgetAvailable(budget,"analysis"))break; results.push(await collectOneNativeV3TokenV333(env,budget,row,headBlock)); }
  return {status:"SCHEDULED_NATIVE_V3_COLLECTOR_COMPLETE_V333",headBlock,tokens:selected.length,processed:results.length,requestsUsed:safeNumber(budget.totalUsed),requestLimit:NATIVE_V3_COLLECTOR_REQUEST_LIMIT_V333,results};
}

